INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution Solo 2000', 'Dance Dance Revolution Solo 2000 is the second special one-player version of the Dance Dance Revolution series of music video games. It was released as an arcade game by Konami on December 15, 1999. Although only officially released in Japan, units exist worldwide. DDR Solo 2000 features 36 songs, 20 of which are new to Dance Dance Revolution.' FROM games WHERE igdb_id = 135510 ON CONFLICT (game_id, language_code) DO NOTHING;
