INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('engacho-for-wonderswan', 267417, '1999-10-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co73qf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Engacho! for WonderSwan', 'Engacho! is based on a popular Japanese children game. A little boy named Sunzuki wants to prove to his angry father that he is not a coward and can stand up against the terrible monsters of the Oops Five group. Those five guys are extremely ugly and can contaminate him with an awful disease the moment they touch him. Suzuki has to run away before they can catch up. Enter a room with the Oops Five monsters and move in different directions, while trying to avoid collision. The catch is that each monster has its own movement style. One of them will always imitate Sunzuki and move into the same direction as he; another will, on the contrary, move into the opposite direction, etc. By planning ahead, the player must make moves correctly and make it to the exit before Oops Five gets the boy. There are different modes in the game, such as training, in which the player faces just one monster of the player''s choice and get used to its patterns; puzzle mode, which takes the player through a series of rooms with different shapes and monsters; and battle mode, in which the player is thrown into large rooms where all Oops Five members roam freely. Gameplay is turn-based.' FROM games WHERE igdb_id = 267417 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 267417 AND p.igdb_id = 57 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('panzer-general-3d-assault', 51856, '1999-09-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57fk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8l4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer General 3D Assault', 'Play in a full 3D environment of WWII. The next instalment of the famous Panzer General series got a new game system, totally redesigned interface and fresh 3D graphics. This strategic simulation will awe you! Promote your best commanders and give them the best equipment to get the job done. Time is one of your enemies so be decisive! Crush all resistance under the steel treads of your tanks in a war that can easily be tailored to your commanding skills. Play historic campaigns as one of the most famous commanders of the USA, UK, Free France and Germany. Soldiers on the battlefields of North Africa, Western and Southern Europe await your orders, Panzer General.' FROM games WHERE igdb_id = 51856 ON CONFLICT (game_id, language_code) DO NOTHING;
