INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Quivering', 'Classic Retro point and click adventure from yesteryear. Set in the dark and foreboding village of Warty Hollow, The Quivering follows the fortunes of young Spud, as he tries to save his uncle, Olivetti Franken-Stamp, from the diabolical spell cast upon him by the big cheese from Hell, Big D.' FROM games WHERE igdb_id = 8943 ON CONFLICT (game_id, language_code) DO NOTHING;
