INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('growlanser', 21309, '1999-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2wiq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8j0u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Growlanser', 'Growlanser is a fantasy SRPG (strategy role-playing game), and the first in the Growlanser series of games.  The main character is Carmaine, an orphan raised by the palace royal magician, Sandra. Prophesied as an infant to become either "the darkness to destroy the world" or "the light which saves it", Sandra carefully watches over him and never allows him to leave Rolandia''s capital city, Rosaria, or have any contact with the outside world. However, throughout his childhood Carmaine experiences strange and vivid dreams of people and places he knows nothing about. When at last he becomes old enough, Sandra tells him it is time to go out and explore beyond the city gates. Accompanied by Tippi, his tiny fairy-like companion, he leaves the city to discover his destiny.' FROM games WHERE igdb_id = 21309 ON CONFLICT (game_id, language_code) DO NOTHING;
