INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sesame Street: Elmo''s ABCs', 'Sesame Street: Elmo''s ABCs is based on the 1980s computer game Letter-Go-Round. Instead of Sesame Street characters, such as Big Bird, Elmo finds a letter that goes merry-go-round to saying how the letters were. They solve by checking the controls to determine the letter.' FROM games WHERE igdb_id = 49933 ON CONFLICT (game_id, language_code) DO NOTHING;
