INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dive-alert-beckys-version', 69075, '1999-08-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7i5c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sco74p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dive Alert: Becky''s Version', 'Dive Alert: Becky''s Version is an RPG for the Neo Geo Pocket Color. There is another version of Dive Alert called Dive Alert: Matt''s Version. The player takes control of a character named Becky. The game takes place in the future and the world is primarily surrounded by water. The only land is a small patch called Terra. The player must prove their worth to be accepted on to Terra by proving their skill as a submarine commander and destroying enemy vessels. Becky''s version features different characters, items and boats from Matt''s Version. These are logged in a device similar to a Pokédex (from Pokemon). Battles take place against enemy ships and a radar view is used to help the player guide torpedoes towards the enemy vessels. Much of the game is text-based with animated cutscenes. The game features the ability for two players to link up Neo Geo Pocket Color units to exchanges ships and data, and to battle one on one. The game also features battery back-up and a training mode.' FROM games WHERE igdb_id = 69075 ON CONFLICT (game_id, language_code) DO NOTHING;
