INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pussy-love-story-from-titanic', 227822, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5u27.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sck6z4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pussy: Love Story from Titanic', 'Pussy: Love Story from Titanic is a single player game which contains platform and falling brick puzzle solving elements. Gameplay is similar to the game Popils. The story behind the game is that Leonardo won a ticket to travel on the Titanic''s maiden voyage. There he met the girl of his dreams, Kate. However Kate was rich and Leonardo was poor and worse, a thief. Their love was forbidden. The game consists of a series of fifty puzzles in which the objective is to get Kate & Leonardo to meet. Kate is usually on top of a parapet or trapped behind a wall shouting ''Help'' and the player must guide Leonardo to her. To solve these puzzles Leonardo can climb ladders and, with his mighty fist, he can smash bricks. Smashed bricks disappear and the bricks above them will fall down to take their place. Some bricks are hollow and cannot be smashed, others will explode. The game also features teleports, which the manual assures were a common feature on the original Titanic, enemies to deal with, and two lengthy platform sequences where Leonardo must traverse the length of the Titanic. Passwords are used to enable games to be restarted at later levels.' FROM games WHERE igdb_id = 227822 ON CONFLICT (game_id, language_code) DO NOTHING;
