INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Michinoku Hitou Koimonogatari Kai', 'Michinoku Hitou Koi Monogatari Kai is the "sequel" or better said is an updated version to Michinoku Hitou Koi Monogatari that was a mix between a first person adventure game and a hanafuda game that tells the story of a young photographer that travels around the northeast part of Japan playing hanafuda games and taking pictures of the places that he visit. In this "sequel" the game features hints to help the player win in the hanafuda games.' FROM games WHERE igdb_id = 64660 ON CONFLICT (game_id, language_code) DO NOTHING;
