INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperLite 1500 Series: Shinsei Toire no Kakosan', 'Shinsei Toire no Hanako-san [SuperLite 1500 Series] is a first person adventure game based on the Hanako-San tale, in the game the player takes the role of one of 3 girls that are friends at school and wants to know more about the hanako legend. The game takes places in 4 chapters and features CG rendering and full japanese voice acting. There are different endings depending of the player choices during the girl.' FROM games WHERE igdb_id = 382913 ON CONFLICT (game_id, language_code) DO NOTHING;
