INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M25 Racer', 'Arcade racing in and around London in a variety of cars. Compete in three leagues - small cars, luxury sports cars and GT racers on your way to winning the title and the ultimate car. In this UK-customised racing game you drive on the left, knock down Gatsos (speed cameras), and get chased by police in Vauxhall Astras and much more.' FROM games WHERE igdb_id = 12896 ON CONFLICT (game_id, language_code) DO NOTHING;
