INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL Blades of Steel ''99', 'Non-stop NHL action! The newest all-star in the Konami Sports Series hits the ice! Get ready for a whole new game! NHL Blades of Steel ''99 hits the ice with all the NHL players, stats and action. Motion captured animation, adjustable team strategies and fully detailed NHL stadiums with real ice conditions. Updated 98-99 rosters called out by NHL TV announcer Randy Hahn. Trade players and sign free agents. Full season stat tracking and league leaders.' FROM games WHERE igdb_id = 3562 ON CONFLICT (game_id, language_code) DO NOTHING;
