INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rainbow-despair', 337444, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9t55.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvzu5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainbow Despair', 'Let me tell you a tale of that awesome power that shook the very heavens from their foundations many years ago. The power commonly called Rainbow Despair. My tale begins, innocently enough, with a 16 year old girl named Molly Despair. Enrolled in the academy of witchcraft in the southern part of the kingdom of Elzdor, she was being instructed in those magical arts essential to a woman of high stature. Spells for cooking delicious meals, creating beatiful quilts and decorations, entertaining guests, and other highly useful tasks made up Molly''s daily studies. But Molly was not interested in such things. She dreamt of a life of high adventure, not high society. And so, one day, she left the school of witchcraft to make her mark on the world as an adventurer. Accompanied by her friend and familiar, Larry the cat, and armed with her trusty broom, she was determined to succeed. Little did she know that the forest surrounding the academy of witchcraft was filled with strange and vicious monsters who loved to devour little girls who were foolish enough to wander into their domain. And so, my story begins.' FROM games WHERE igdb_id = 337444 ON CONFLICT (game_id, language_code) DO NOTHING;
