INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chutes and Ladders', 'Chutes and Ladders is an adaptation of the classic children''s board game of moving up and down. Players proceed along a board advancing closer to the finish when they land on a ladder space and falling back when they land on a chute space. The PC version is a kid friendly interpretation designed for 4-6 year olds.' FROM games WHERE igdb_id = 92928 ON CONFLICT (game_id, language_code) DO NOTHING;
