INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('varicella', 9519, '1999-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xrh.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Varicella', 'You are Primo Varicella, Palace Minister at the Palazzo del Piemonte. This title is unlikely to impress anyone. Piedmont is the laughingstock of the Carolingian League, and the Palace Ministry has devolved into little more than a glorified (and not even especially glorified) butlership. But now that King Charles has died of a sudden illness, you have a prime opportunity to advance your position by becoming the regent of the five-year-old Prince Charles. Your fellow ministers will no doubt try all sorts of unseemly tactics in their quest for the throne. Some will try bribery. Others will employ treachery. A few may even resort to brute force. But would Primo Varicella stoop to using one of these methods? Perish the thought! You''re better than that. You shall employ all three.' FROM games WHERE igdb_id = 9519 ON CONFLICT (game_id, language_code) DO NOTHING;
