INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('catwoman--1', 67337, '1999-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2sdg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqnkl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catwoman', 'In the Catwoman game, the main Batman villainess gets her own storyline. Talia attempts to hire Catwoman for a mission to steal a crystal skull, but Catwoman decides to keep the valuable item for herself, unaware that Ra''s al Ghul intends to use it to destroy Gotham. Catwoman possesses a variety of moves to help her traverse and combat enemies across nine levels filled with adversaries and platforms. She can utilise her claws for attacks, perform wall jumps, flips, ledge grabs, and swing with her whip. Additionally, she has a stealth option that enables her to blend into the level''s background, allowing her to move silently and unnoticed.' FROM games WHERE igdb_id = 67337 ON CONFLICT (game_id, language_code) DO NOTHING;
