INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zeta''s World', 'Our brave Smiley Hero had just defeated the terrible Evil Wizard and was enjoying a quiet and calm endgame... when the beam came from the skies and striked him (or her). When the beam cleared out, he (or she) had been whisked by unknown forces, into a bizarre world unlike anything he (or she) ever experienced! You are now that hero! Can you brave your way through this world of perilous islands, dangerous beasts, overseen by a dimensionally-wrenching tower of doom?' FROM games WHERE igdb_id = 337446 ON CONFLICT (game_id, language_code) DO NOTHING;
