INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kaze-no-klonoa-moonlight-museum', 37499, '1999-05-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qhd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjmzq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaze no Klonoa: Moonlight Museum', 'Klonoa and his friend Huepow come across a young crying girl who tells them that the moon has been divided into fragments and stolen by a mysterious group of artists that reside in the nearby Moonlight Museum. Determined to help, the duo rush off to the Museum''s entrance, and once they come inside, they are greeted by a painter named Picoo who traps them inside a piece of artwork. Klonoa and Huepow must fight their way through five worlds within the Museum itself before finding the source of all their troubles and restoring the moon to the sky.' FROM games WHERE igdb_id = 37499 ON CONFLICT (game_id, language_code) DO NOTHING;
