INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kawaii Pet Shop Monogatari', 'Kawaii Pet Shop Monogatari is an RPG where you manage a pet shop, raise animals, participate in competitions, and travel for events. Complete various requests to improve your shop''s reputation. The protagonist''s grandmother, who runs a pet shop, falls ill and is hospitalized. In her place, the protagonist takes over managing the pet shop and sets off on an adventure with excellent pets to find ingredients for a medicine to cure the illness.' FROM games WHERE igdb_id = 228580 ON CONFLICT (game_id, language_code) DO NOTHING;
