INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('little-witch-parfait-kuronekojirushi-no-mahouya-san', 124645, '1999-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2z5c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scbu31.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Witch Parfait ~Kuronekojirushi no Mahouya-san~', 'Parfait Sucreal is a young witch, who is yet in training and full of clumsiness in raising a potion shop called Black Cat Market run by her mother and Parfait''s black cat, Sakemas, who can amazingly talk. A year ago from the time this game was set, her mother had died from an illness - her father was a famous wizard who died from saving the kingdom when Parfait was young. At the beginning, Parfait introduces herself and tells the player that she is almost at the risk of losing her beloved shop (the only remains of her mother), for Parfait has to pay the debt of 1,000,000G (gold) by 12 months to keep the shop running. As a normal shop, there seems no hope for raising the Black Cat Market''s fame. The player''s motive is to collect this debt by 12 months in various ways such as putting cauldron-made potions to the shop counters for customers, accepting potion orders at the end of the day and sell her potions on the street. As Parfait gains more experience via studying in the library or creating potions, her levels will rise (with a maximum of six stars) which enables her to succeed more on potions that are high-leveled. Many places may trigger the encounter with other important characters whose futures the player must decide by motivating Parfait.' FROM games WHERE igdb_id = 124645 ON CONFLICT (game_id, language_code) DO NOTHING;
