INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('doko-demo-issyo', 72565, '1999-07-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hmi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclvcu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doko Demo Issyo', 'Doko Demo Issyo (どこでもいっしょ, Together Everywhere) is a 1999 Video Game developed by Bomber Express and published by Sony Computer Entertainment Inc. for the PlayStation, released on July 22, 1999 in Japan. Doko Demo Issyo was one of the games that used the PocketStation; it was instrumental in making the device sell so well in Japan. It is the first game in the Doko Demo Issyo Series. Doko Demo Issyo is a communication game, a game where you interact with the characters through words and phrases. The player can choose from five characters known as Pokepi and interact with them in an apartment. They can be taught words, and the player can answer questions asked by them. The biggest feature of Doko Demo Issyo is its compatibility with the PocketStation, a handheld device that often came packaged with the game, and its reliance on the device made the PocketStation required to play the game. It allowed the player to take any of the Pokepi with them anywhere, and they can continue to interact through the device. A remaster of the game was released on the PlayStation Portable on December 7, 2004 for the franchise''s 5th anniversary. A port of the original game, separate from the remake on the PSP, was also released on the Playstation Vita in 2013.' FROM games WHERE igdb_id = 72565 ON CONFLICT (game_id, language_code) DO NOTHING;
