INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Romancia: Another Legend', 'Romancia: Another Legend is a remake of the classic RPG Romancia with improved graphics and mouse support. You are cast as a dashing prince who sets out to rescue the princess of the kingdom from the hands of an evil dragon. Gameplay is a mixture of 2D side-scrolling action with RPG elements as you can equip weapons, chat with NPCs and receive quests which usually involve going from the town to the dungeons and retrieving an item or slaying a specific monster.' FROM games WHERE igdb_id = 71968 ON CONFLICT (game_id, language_code) DO NOTHING;
