INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ncaa-final-four-2000', 43716, '1999-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/deapunpj4r22qai3whmz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA Final Four 2000', 'Improving from last year?s mark NCAA? Final Four? 2000, once again, is the most complete NCAA basketball game of the year. With virtually every Division I team represented, you?ll be sure not to miss any of the big games. Pick your team and track their progress. You can also check your school?s status all the way down to the Final Four with the All-New Bubble Watch. Now you?ll know exactly who?s in, who?s out and who is "on the bubble". With Exhibition, Season, Tournament and Arcade modes, you decide your level of dedication. Looking to improve your school?s roster? We?ve also included a new Recruit Player feature. Put yourself in the game and take your school to the big dance. Work your way up from Freshman to Senior difficulty levels as you build confidence and gain experience. The whole year, you are immersed in collegiate basketball intensity with authentic fight songs, crowd chants and last minute buzzer beaters. From Top 10 match-ups to cross-town rivalries, 989 Sports delivers the most intense collegiate basketball experience of the year.' FROM games WHERE igdb_id = 43716 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 43716 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
