INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 19: The Sugoroku', 'Simple 1500 Series vol.019 The Suguroku is a board game based on the Sugoroku game, the game features different boards and can be played by up to 4 human players at the same time. Sugoroku is a game with which you can step one block by one from start to the end of various stories using a dice.' FROM games WHERE igdb_id = 203006 ON CONFLICT (game_id, language_code) DO NOTHING;
