INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shinkai Densetsu Meremanoid', 'Partially based on a little-known anime television series by Triangle Staff that aired in 1997. It is a fantasy role-playing game where the player takes the role of a mermaid trying to find the secrets of her race. The game uses a turn-based fighting system with special moves and attacks. The blocky graphics were typical for a PlayStation title of the era.' FROM games WHERE igdb_id = 112178 ON CONFLICT (game_id, language_code) DO NOTHING;
