INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectral Tower II', 'Neverland is a lush, green world told of in ancient traditions. Spectral Tower II is the second game in the RPG series released by Idea Factory for the PlayStation One console, the game begins with an intro in which the adventurer arrive to a town and after that he will meet another adventurer that will take him to the ruins of the evil tower that is located in the desert. The gameplay is in third person perspective using an overview view meanwhile the player is exploring the different floors of each tower, and also a third person perspective for the battle parts.' FROM games WHERE igdb_id = 281681 ON CONFLICT (game_id, language_code) DO NOTHING;
