INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cutthroats-terror-on-the-high-seas', 26184, '1999-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nulhakg2eoiv9lor27wb.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cutthroats: Terror on the High Seas', 'The game is set in the 17th century in the Caribbean and unlike most pirate games, it is mostly historically accurate. The game world is covered with settlements according to the time period the player picks at the start (and evolves accordingly as the game progresses) and each settlement is ruled by one of the five new world powers, Spain, England, France, The Netherlands and Denmark. Also some settlements are ruled at certain times by independent rulers, e.g. Tortuga and Belize. These settlements can be attacked by the player, meaning his crew, with weapons the player chose, will land at the town and can then be controlled to burn and pillage it. Other than this the player controls a ship unit upon a map of the Spanish Main and can plot courses to pins which represent towns; however, if an NPC ship is close enough to the player (these ships spawn at the settlements with goals such as trade between towns or to find pirates), the player will be alerted and go into a smaller bird''s-eye map in which they can raise flags to either enter diplomacy with the ship such as asking for information, raise nation flags to avoid them, or obviously raise the Jolly Roger to attack them. Ship combat is worked much as town combat with the player controlling his ship(s) with advanced controls such as where to aim cannon, and what type of shot, right down to scuttling the ship or setting it ablaze.' FROM games WHERE igdb_id = 26184 ON CONFLICT (game_id, language_code) DO NOTHING;
