INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Independence War: Deluxe Edition', 'A guerilla war has been raging in space for centuries. Human colonies are breaking away from Earth''s control, declaring independence from the Commonwealth. As a Commonwealth Navy commander, your mission is to stop the Indie rebels and their attacks of terror and random piracy.' FROM games WHERE igdb_id = 36201 ON CONFLICT (game_id, language_code) DO NOTHING;
