INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zoku Mikagura Shoujo Tanteidan: Kanketsuhen', 'Zoku Mikagura Shoujo Tanteidan～Kanketsu Hen～ is an adventure game that lets players enter into the mystic Taisho and early Showa periods and find out the truth behind each case. The number of scenarios has been increased largely and the “inference trigger” feature is kept intact to deliver the most enjoyable detective game experience.' FROM games WHERE igdb_id = 60574 ON CONFLICT (game_id, language_code) DO NOTHING;
