INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('castrol-honda-world-superbike-team-superbike-2000', 25247, '1999-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob4e1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar57xh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castrol Honda: World Superbike Team - Superbike 2000', 'Castrol Honda Superbike Racing is a simulation-style racing game featuring the Honda RVF-RC45 motorbike and 14 real-world venues. Adjust your bike''s gear-ratio settings, transmission, and tire composition before competing against seven computer-controlled riders in either a single race or a 13-event tournament. Individual practice and training sessions allow you to learn each track''s layout and optimal racing lines prior to the event. View the action from a first-person perspective behind the bike''s handlebars or from a third-person vantage point. Six difficulty levels and various other customization settings let you determine the degree of realism on each course. You can also challenge a friend to a head-to-head race via split-screen display. allgames' FROM games WHERE igdb_id = 25247 ON CONFLICT (game_id, language_code) DO NOTHING;
