INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puyo Puyo Da!', 'Puyo Puyo DA! is a Dance Dance Revolution based game for the Dreamcast with Puyo Puyo characters. This game is based off a Disc Station game previously featuring Ellena Stevens. In contrast to most Puyo Puyo games, a large majority of the text in this game is in English. It was Compile''s last Puyo Puyo game to be released on a Sega system. (The last Compile game in the series, Puyo Puyo Box, released a year later.)' FROM games WHERE igdb_id = 4353 ON CONFLICT (game_id, language_code) DO NOTHING;
