INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer 40,000: Agents of Death', 'Agents of Death was an FPS (First Person Shooter) video game, that was produced for the PC by the Polish game developer Mirage Media (also referred to in some places as Mirage Interactive). In the game''s story line, the player leads a team of Imperial Assassins to eliminate a Heretical Imperial Commander, known as the Cardinal. He is under the power of a Daemon Prince and must be stopped by the Assassins, before ruin befalls the Cardinal''s world.' FROM games WHERE igdb_id = 32602 ON CONFLICT (game_id, language_code) DO NOTHING;
