INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nihon-pro-mahjong-renmei-kounin-tehodoki-mahjong-nyuumon-hen', 369847, '1999-03-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coajp2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4a5t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nihon Pro Mahjong Renmei Kounin: Tehodoki Mahjong Nyuumon-hen', 'Nihon Pro Mahjong Renmei Kounin - Tehodoki Mahjong Nyuumon-hen is a educational game in which the player will learn the different rules of mahjong. The game will use video tutorial and quiz tests to teach the player evaluate his understanding. Mahjong is a game for four players that originated in China. Mahjong involves skill, strategy, and calculation, as well as a certain degree of chance. Depending on the variation which is played, luck can be anything from a minor to a dominant factor in success. In Asia, mahjong is also popularly played as a gambling game. In the game, each player is dealt either thirteen or sixteen tiles in a hand (depending on the variation being played). On their turn, players draw a tile and discard one, with the goal of making four or five melds (also depending on the variation) and one pair, or "head". Winning comes "on the draw", by drawing a new or discarded tile that completes the hand. Thus a winning hand actually contains fourteen (or seventeen) tiles.' FROM games WHERE igdb_id = 369847 ON CONFLICT (game_id, language_code) DO NOTHING;
