INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bass-masters-classic', 49867, '1999-11-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7p0q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3wc8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bass Masters Classic', 'Now when you can''t get out to the lake, you can go fishing on your Game Boy Color with Bassmasters Classic. Choose from a variety of lures and hit your favorite fishing hole. You cast the line by stopping a power meter at one of five positions more power equals more distance. After you cast the line, you must wait for a fish to strike. When it does, get ready for a fight. Once you get the fish to the boat the game is not over, as you must stick you hand into the water and grab the catch. If you can''t get a hold of it within three tries, you''ll be telling stories about the one that got away. All of this action takes place in Practice and Tournament modes. If you can''t get to the lake, bring the lake to you with Bassmasters Classic.' FROM games WHERE igdb_id = 49867 ON CONFLICT (game_id, language_code) DO NOTHING;
