INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 15: The Pachinko', 'With 3 types of original pachinko machines, this game delivers a real sense of playing inside a pachinko parlour. The 3 pachinko machines available are "CR Love Love Project 2", a LCD machine offering diversified reach actions, "CR Star Robot" with heated double and triple reach actions, and "Surfing Island", a colourful machine in the motif of aloha T-shirts.' FROM games WHERE igdb_id = 209498 ON CONFLICT (game_id, language_code) DO NOTHING;
