INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legend of the River King GBC', 'The Game Boy Color version of the fishing role playing game Legend of the River King. The game consists of two separate modes: "Fish" which is the main RPG mode where you set out to find the Guardian fish. "Raise" in which you purchase a fish tank and raise a small fish in hopes for it to grow. Similar to that of a Tamagotchi.' FROM games WHERE igdb_id = 20515 ON CONFLICT (game_id, language_code) DO NOTHING;
