INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ayrton Senna Kart Duel Special', 'Ayrton Senna Kart Duel is a series of Karting-based 3D racing video games named after famous Brazilian kart and Formula One racer Ayrton Senna. In Japan, the games were developed and published by Gaps, which were released exclusively for the PlayStation under the license of Ayrton Senna Foundation, and technical advice by Yamaha and Dunlop. It was published in the european market by Sunsoft.' FROM games WHERE igdb_id = 285994 ON CONFLICT (game_id, language_code) DO NOTHING;
