INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legend of the River King 2', 'The second game in the River King Franchise for the Game Boy Color. A fishing role playing game where you travel the world to catch up to 60 kinds of fish, shellfish, plats and insects. But beware of local wildlife attacking you for your catch! Legend of the River King 2 is a massive role-playing adventure that features all manner of angling from fresh water fly-fishing to deep sea trolling. A new trade mode allows you to trade your fish for produce with farmers in Harvest Moon GBC2!' FROM games WHERE igdb_id = 20516 ON CONFLICT (game_id, language_code) DO NOTHING;
