INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ancient-conquest-the-golden-fleece--1', 7713, '1999-04-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ccd3saghdaryxclyzi65.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/z5xj0vmbxpagrubcbm9s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancient Conquest: The Golden Fleece', 'Ancient Conquest is set in the fictional days when heroes like Hercules and Zetes lived, days that we know from legendary myths. The objective of the game is to get the Golden Fleece. To reach the objective, players will have to build their navy, the legendary ship Argo, earn money while exploring natural resources, like amber, fish and Leviathans. While playing the game, players will have to fight against monsters (harpies, medusas, cyclops, minotaurs, etc.), sea creatures (sharks, crocodiles, sea-serpents, swordfish), wizards, survive natural disasters as well as the mighty Persians and Barbarians who robbed you of your ships and settlements. To overcome obstacles you have to attract ancient heroes to help you on your quest, for their skills will help you on your journey.' FROM games WHERE igdb_id = 7713 ON CONFLICT (game_id, language_code) DO NOTHING;
