INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution Solo Bass Mix', 'Dance Dance Revolution Solo Bass Mix is the first special one-player version of the Dance Dance Revolution series of music video games. It was released as an arcade game by Konami on August 19, 1999. Although only officially released in Japan, units exist worldwide. DDR Solo Bass Mix features 16 songs, all of which are new to Dance Dance Revolution. Most of the music comes from the Dancemania BASS albums,hence the name "Solo Bass Mix". A Solo Bass Mix machine can be upgraded to DDR Solo 2000. This is the first game that features a live-action intro.' FROM games WHERE igdb_id = 135509 ON CONFLICT (game_id, language_code) DO NOTHING;
