INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('70-s-robot-anime-geppy-x', 79588, '1999-05-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5wmv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5haa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '70''s Robot Anime Geppy-X', 'Geppy-X is a 2D side-scrolling shoot-em-up developed as an affectionate parody of the 1970s super robot era of mecha anime pioneered by Go Nagai and Ken Ishikawa. In it, you play as a super robot fighter squadron in an alternate universe 1970s, fighting against alien invaders from the Space Devil Empire. The titular robot has three transformations all modeled after famous 1970s super robots, as well as a super form known as Geppy-XX. Stages are presented like actual anime episodes, and the game makes use of the PlayStation''s full motionn video capabilities to include actual animations made specifically for the game, with an opening, part A, eye-catch, part B, ending theme, and next episode preview. They even have fake commercials that play in between the eye-catches.' FROM games WHERE igdb_id = 79588 ON CONFLICT (game_id, language_code) DO NOTHING;
