INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peacemaker: Protect, Search & Destroy', 'Peacemaker is a 3D Shooter where you are in control of a helicopter. Playing as a pilot who is tasked by the UN to take down Terrorists, you will engage in 21 action filled missions with multiple helicopters to chose from with objectives that range betwen base defense, escore and assault. You can choose to either use the "nose" camera or "chase" camera for your preference' FROM games WHERE igdb_id = 382364 ON CONFLICT (game_id, language_code) DO NOTHING;
