INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dead-in-the-water', 22846, '1999-04-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4zhu.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead in the Water', 'Dead in the Water is all about the thrills, chills, and spills of powerboat racing. Choose from 14 different boats, and then hit one of the nine courses, each with unique obstacles, conditions, and jumps. After winning a race, upgrade your weapons to keep a tactical advantage over the competition. If racing for speed is not your style, play the battle mode and try to destroy all of your opponents. Thanks to the realistic water physics, swells will throw your boat into the air, currents will affect your speed based on their direction, and landing hard after a jump will put the boat under water and cause a major slowdown. Can you handle all of the action of Dead in the Water?' FROM games WHERE igdb_id = 22846 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 22846 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
