INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider: The Last Revelation - The Times', 'Tomb Raider: The Last Revelation - The Times is a downloadable bonus level from Tomb Raider: The Last Revelation. It is available only on the PC, and unlike previous expansions, does not require the disc for Tomb Raider: The Last Revelation. This bonus level was a promotion for The Times newspaper celebrating the discovery of the Tutankhamun''s tomb 75th anniversary.' FROM games WHERE igdb_id = 68115 ON CONFLICT (game_id, language_code) DO NOTHING;
