INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Project Studio: Blue Version', 'From the main menu users can choose the type of media they wish to create including greeting cards, signs, birthday kits, banners, photos, stationery, envelopes, calendars, paper crafts, certificates and stickers. The user can use several included images and templates or they can import custom images into the picture. Each CD contains 81 different Pokémon. The kind of Pokémon they get depends on whether they are running the Red CD or the Blue CD. For example only the Red CD has Mewtwo, while Raichu only appears in the Blue CD.' FROM games WHERE igdb_id = 181515 ON CONFLICT (game_id, language_code) DO NOTHING;
