INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Creed', 'The Creed is a 1999 action-adventure game created by Australian developers Insomnia Entertainment and Dreamtime Interactive, and published by Electronic Arts and Midas Interactive. The game is a cyberpunk-themed action-adventure game set in a partial open world, allowing players to complete open-ended missions for the game''s various factions. Upon a limited release in the Asia-Pacific, The Creed received praise from Australian publications for its atmosphere and environmental design.' FROM games WHERE igdb_id = 78187 ON CONFLICT (game_id, language_code) DO NOTHING;
