INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of Kings', 'King of Kings is a Chinese MMORPG first released in 1999 by DigiWin Software, based on a 1996 text MUD from National Tsing Hua University. Featuring large-scale PvP, guild warfare, and a classic fantasy setting. The original version ran until 2004, spawning sequels before shutting down in 2009' FROM games WHERE igdb_id = 360976 ON CONFLICT (game_id, language_code) DO NOTHING;
