INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pga-european-tour--1', 176028, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co47yj.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PGA European Tour', 'PGA European Tour is a golf game that makes use of the official European Tour license. It offers only four courses, specifically Quinta do Lago in Portugal, Kungsängen in Sweden, Druids Glen and the K Club in Ireland. Players can choose to play a quick match, a non-tour golf game or participate in the real tour. The non-tour option includes several modes: in Strokeplay players need to get the least number of strokes in order to win, in Matchplay the goal is to win more holes, while in Skins holes are played for money (winners of holes one to six get 100 euros, seven to twelve - 200 euros, thirteen to eighteen - 300 euros). Up to four players can play non-tour games, and some options allow teams of two to face each other. Participation in the tour itself is a simulation of the real thing. Players start as amateurs, and can select to play as one of 64 European golfers like Nick Faldo and Jose Maria Olazabal, or create their own custom character. To reach professional status it''s necessary to reduce the handicap to zero and finish in the top 8 of the Amateur Challenge Tour. Reaching the top 8 of the Professional Challenge Tour guarantees an entry to the European Tour Qualifying School, the final hurdle before advancing to the European Tour. In order to keep playing there one must not fall out of the top 32 golfers in the rankings.' FROM games WHERE igdb_id = 176028 ON CONFLICT (game_id, language_code) DO NOTHING;
