INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart Phonics', 'JumpStart Learning Games Phonics is an educational game released by Knowledge Adventure in 1999, based on the JumpStart Kindergarten: Why Did the Bus Stop? video. Players explore three main locations - the Barn, Fire House, and Train Station - collecting clues to solve the mystery of why a bus stopped. The game''s core mechanics involve completing activities at each location, gathering clues that appear in the Look and Listen window, collecting objects from different areas, and deducing the bus stop reason from four randomized clues. Upon successfully solving the mystery, players earn a certificate and can print game characters and objects. Each game features multiple possible explanations for the bus stop, with clues randomized at the start, ensuring a unique experience each time.' FROM games WHERE igdb_id = 358412 ON CONFLICT (game_id, language_code) DO NOTHING;
