INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Global Force', 'Global Force is a tactical RPG in which the player takes the role of the members of the Global Force a organization that defends the peace in the planet against different enemy armies. The game is a tactical rpg in which the player got a limited number of units that can use in each turn and those unit got a limited range of movements. There are different vehicles like planes, tanks and others to use.' FROM games WHERE igdb_id = 343702 ON CONFLICT (game_id, language_code) DO NOTHING;
