INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goemon: Mononoke Sugoroku', 'Goemon: Mononoke Sugoroku is a video game for the Nintendo 64, released in 1999. The game is based on the Goemon series and despite the series'' relative popularity in the west for the system, the game was released only in Japan. The game is based on the Japanese board game Sugoroku, populated with Konami''s array of Ganbare Goemon characters. Up to four players control two dice, and take them in turns to control Goemon, Ebisumaru, Sasuke, or Yae over pre-rendered boards that resemble previous locations in the Ganbare Goemon series.' FROM games WHERE igdb_id = 3507 ON CONFLICT (game_id, language_code) DO NOTHING;
