INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Mahjong Kiwame Tengensenhen', 'Pro Mahjong Kiwame is a four player Riichi mahjong game, unlike most one-on-one Mahjong games released at the time and the modern casual games. Players take and discard tiles until they''ve completed hands by forming groups and pairs.' FROM games WHERE igdb_id = 97875 ON CONFLICT (game_id, language_code) DO NOTHING;
