INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatal Fury: Wild Ambition', 'Fatal Fury: Wild Ambition re-tells the story of Terry and Andy Bogard''s fight to avenge their father''s death at the hands of Geese Howard with the use of a fully polygonal engine. The game is a 3D one-on-one fighting game that uses the standard Fatal Fury control scheme under a brand new 3D arena. Choose from a selection of classic Fatal Fury characters that includes 2 all-new characters, plus 2 secret guest stars. Game modes include arcade, vs, and story mode, which adds pre-rendered CGI cutscenes between certain fights.' FROM games WHERE igdb_id = 346147 ON CONFLICT (game_id, language_code) DO NOTHING;
