INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paca Paca Passion Special', 'The third title in Japan-only rhythm game series Pacapaca Passion. Paca Paca Passion Special is the third and last game in the Paca Paca Passion series of music games made by Namco and that are conversion of Arcade Machines made too by Namco. The game features different melodies and game modes, and also a vs mode against a computer or another human player. Since this is the latest one in the series the game features the best graphics in the series with good cartoon 3d graphics.' FROM games WHERE igdb_id = 329386 ON CONFLICT (game_id, language_code) DO NOTHING;
