INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xuan-yuan-sword-mists-beyond-the-mountains', 85727, '1999-12-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co73wb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2aj8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xuan-Yuan Sword: Mists Beyond the Mountains', 'This Game is one of the most popular RPGs in the Chinese Speaking Area and has won many awards around Asia. The game story takes place in an era of collision between East and West, covering a wide range, spanning Eurasia, the Arab World, Francia, and China. Xuan-Yuan Sword: Mists Beyond the Mountains is a classic turn-based RPG. Under the orders of Pepin III, the Frankish Knight Septem has embarked on a long journey to seek the Invincible Arts of War. Starting from the canals of beautiful Venice, the great knight''s path has spanned the Middle East, Western Regions on his way to the mystical orient. In his adventures, Septem has drawn into the intricate power disputes between local powers, along with the decade-spanning ambitions of the dark lord, Satan. China enjoys peace and prosperity under the rule of the Tang Empire, Europe finds itself embroiled in the Dark Ages, the Arabian Empire is ascendant, and all the while, the march of progress brings these disparate cultures together. From ancient times, Chinese legends have spoken of the Xuan-Yuan Sword and Spirit Fusion Pot, along with the rise of great legends in the new era... The scope of Xuan-Yuan Sword: Mists Beyond the mountains covers a wide range, spanning all of Eurasia and covering the Arab World, Francia, and China. From the canals of Venice, Damascus to the beautiful Chang’an, the story introduces unique architectural styles, clothing, food, and customs. Players can use the Spirit Fusion Pot to capture enemies in battle. Items and monsters can be used to craft a new item or monster from the codex. Users can craft items and monsters from the Eastern or Western altars, which the resulting item differing based on the selected altar.' FROM games WHERE igdb_id = 85727 ON CONFLICT (game_id, language_code) DO NOTHING;
