INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megami Tensei Gaiden: Last Bible II', 'Megami Tensei Gaiden: Last Bible II is a role-playing video game series developed by Multimedia Intelligence Transfer, Sega, and Menue, and published by Atlus and Sega for multiple platforms. Players explore the game world and fight monsters in menu-based battles; players can also attempt to recruit monsters to their party, and can fuse two allied monsters into a single new one to try to get stronger monsters.' FROM games WHERE igdb_id = 265053 ON CONFLICT (game_id, language_code) DO NOTHING;
