INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghoul Panic', 'Ghoul Panic is a comedy action-adventure game developed by Raizing and published by Namco, set in a haunted mansion. The original arcade cabinet was released in July 1999, and ported to the Playstation in April 2000 with additional exclusive game modes including Survival, Adventure and Remix.. Using a light gun, take on the might of vampires, monsters, mummies, skeletons and spooks to open the locked doors and uncover hidden bonuses.' FROM games WHERE igdb_id = 14392 ON CONFLICT (game_id, language_code) DO NOTHING;
