INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skipper & Skeeto: The Shadow of Mr. Shade', 'The fourth game in a series of point-and-click games. Set in a factory of mister Shade. Magnus and Mia can walk, climb, jump, push and pull. You play alternately Mia and Magnus through 4 chapters. Click on mosquito or Alpha for help. Many new exciting characters. More than 200 tasks and puzzles. Learn as you play - facts about plastic, oil, glass and many everyday objects.' FROM games WHERE igdb_id = 22353 ON CONFLICT (game_id, language_code) DO NOTHING;
