INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('faselei', 28401, '1999-12-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co52xi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7m8l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faselei!', 'Faselei! is a Strategy game, developed by Sacnoth and published by SNK, which was released in Japan in 1999. Faselei! is one of the last titles to be released for the Neo Geo Pocket Color and even features digitised lyrics to the game''s main theme. Heavily story driven, this strategy RPG takes place in a time when mechs known as TS are the weapon of choice for combat. Gameplay revolves around the battles and customising your TS between those battles. Battles are part turn based and part real-time. The player inputs their actions at the beginning of the turn. The amount of actions they can input is dependant on their type of TS. Once they have finished their selection everything is played out in real-time for the duration of the turn. This makes thinking about what your opponents and allies will do in advance essential before taking your turn.' FROM games WHERE igdb_id = 28401 ON CONFLICT (game_id, language_code) DO NOTHING;
