INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backstreet Boys: Puzzles In Motion', 'Did you ever puzzle a video? Just imagine a Backstreet Boys music video that has been cut into little square pieces. The individual squares have been scrambled, rotated or even mirrored. How quickly can you put the video back together? How well do you recognize the music clips with A.J., Brian, Howie D., Kevin and Nick? Test your puzzle and musical skills at the same time! If you succeed in solving the 12 clips on one level you''re ready to tackle the 13th tricky video puzzle.' FROM games WHERE igdb_id = 73920 ON CONFLICT (game_id, language_code) DO NOTHING;
