INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman Complete Works: Rockman', 'Relive all the classic adventures of the Blue Bomber with Capcom''s new Rockman Complete Works series! All 6 NES/Famicom games have been reworked and brought to the PlayStation, with all the classic enemies, bosses, weapons, and of course, the evil Dr. Wily! The Rockman Complete Works series was only released in Japan.' FROM games WHERE igdb_id = 84124 ON CONFLICT (game_id, language_code) DO NOTHING;
