INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kalpa-the-sign-of-omen', 238918, '1999-09-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co66h3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclfma.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kalpa: The Sign of Omen', 'In July 1999, a strategy role-playing game developed by Dynasty International Information and published by Soft-World Technology was released along with the well-known computer magazine "Software and CD" in mainland China. This game is called "Kalpa: The Sign of Omen". Due to its low price of 25 yuan for the full version, it attracted a large number of players. Most people were initially scared off by its difficulty, making the most common screen seen at the beginning "defeat." Then, there were a lot of game-breaking bugs, causing many players to have to start over. There was even a rumor online that the game company was treating players as free testers. As a result, the magazine "Software and CD" had to include a patch in its August issue to appease the players'' anger. In September 1999, the "enhanced version" of "Kalpa: The Sign of Omen" was released at a price of 69 yuan. In addition to a big box packaging, the game also came with a full-color manual and a fan comic. The game version was also upgraded to 1.1. This version looked like a deluxe edition, and many players who owned the standard edition were not interested in it. However, this version contained a big secret, which was the perfect ending of the game. The relevant levels were not included in the standard version.' FROM games WHERE igdb_id = 238918 ON CONFLICT (game_id, language_code) DO NOTHING;
