INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stephen King''s F13', 'Stephen King''s F13 is a collection of casual games developed by Presto Studios and released in 2000 by Blue Byte. The title F13 suggests a function key that would follow F12 on standard PC keyboards. The minigames include No Swimming, Bug Splat, and Whack-A-Zombie. The "Frightware" bundle also includes a set of "Screamsavers", "Bump and Thump" sound effects, "Deathtop" backgrounds, and Stephen King''s short novella Everything''s Eventual. Stephen King''s F13 decks out your computer with a horror aesthetic, offering "deathtop" images, "screamsavers," and a trio of minigames. The capper is a novella entitled Everything''s Eventual, a story that brings King''s usual themes into a high-tech context.' FROM games WHERE igdb_id = 74412 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 74412 AND c.slug = 'presto-studios' ON CONFLICT DO NOTHING;
