INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('soul-fighter', 45840, '1999-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co43am.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm78k.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soul Fighter', 'Pick the warrior, thief, or wizard, and fight through five huge levels, each with its own boss. Your main weapons are your fists, but you can pull out weapons for quick kills. You only get so many shots with your weapon before it breaks, though. Gameplay is basic 3D brawling. You will be attacked by one or more enemies, and will need to defend yourself, and attack back. The game features arcade and adventure modes. In the arcade mode, the levels are timed, and you only get 5 lives but you are revived where you died. In adventure mode, you get unlimited retries of each level, but must complete each level on a single life. Note that your objective in each level is to kill every enemy; since the levels have multiple paths, you will need to backtrack often.' FROM games WHERE igdb_id = 45840 ON CONFLICT (game_id, language_code) DO NOTHING;
