INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes V: Umi no Oriuta', 'The Legend of Heroes V: Umi no Oriuta (Cagesong of the Ocean) is the fifth installment in Falcom''s long-running RPG franchise and the final entry in the "Gargarv Trilogy." The title was publish by Falcom initially for the PC on December 9, 1999 and was later remade for the PlayStation Portable by MiCROViSion in 2006.' FROM games WHERE igdb_id = 240540 ON CONFLICT (game_id, language_code) DO NOTHING;
