INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('grauen-no-torikago-kapitel-1-keiyaku', 313975, '1999-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8v3s.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grauen no Torikago: Kapitel 1 - Keiyaku', 'Grauen no Torikago: Kapitel 1 - Keiyaku is the first chapter of a horror movie sold exclusively through the Dreamcast Direct online service. The film is divided into 365 episodes, each lasting one minute. It was impossible to watch all the episodes at once as they opened gradually. From 1 October 1999 to 1 October 2000, it was necessary to connect Dreamcast to the internet daily and download special save files on the VMU that opened new episodes. The servers went offline shortly after the final episode unlocked. Now it is necessary to use a special VMU save or directly extract the videos of the GDI disc image to watch the film. The sequels of Grauen no Torikago were only available to consumers who had finished previous chapters, making later entries exceedingly rare. As of July 2024, a restoration patch has been made by Derek Pascarella that allows you to watch the videos without the vmu save.' FROM games WHERE igdb_id = 313975 ON CONFLICT (game_id, language_code) DO NOTHING;
