INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ide Yosuke no Mahjong Kyoushitsu', 'Ide Yōsuke no Mahjong Kyōshitsu is a Mahjong learning and practice game featuring Mahjong professional Ide Yōsuke. The game has a number of lessons shown with a manga style drawn Ide Yōsuke explaining the rules of the Chinese classic board game of Mahjong, and allows the player to try what they have learn on Mahjong boards.' FROM games WHERE igdb_id = 354912 ON CONFLICT (game_id, language_code) DO NOTHING;
