INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('uno--7', 165365, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4eri.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scelp0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uno', 'UNO, the classic card game of skips, draw-twos, and reverses, has come to the Game Boy Advance. There are two modes of play: Standard and Challenge. Standard has the players keep going until they reach a specified number of points, usually 1000. However, a player only scores points when he gets rid of all the cards in his hand. The points are the total value of the cards left in the opposition''s hands. In Challenge, each player has a set number of points, and a player is eliminated when he reaches the point total. Play continues until one player is left standing. In both modes, you can play against up to three computer-controlled opponents. You can also play a single human opponent via a link cable. As an added bonus, there are three new cards that are not part of the real-world game. Now you can play UNO by yourself.' FROM games WHERE igdb_id = 165365 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 165365 AND ge.slug = 'card-and-board-game' ON CONFLICT DO NOTHING;
