INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bust-a-move-pocket', 43977, '1999-05-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co52xl.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bust-A-Move Pocket', 'Bust-A-Move Pocket, also called Puzzle Bobble Mini, is a Neo Geo Pocket Color version of the Bust-A-Move (Puzzle Bobble) series of puzzle games. It was released on the Neo Geo Pocket Color by Taito in 1999. The format is similar to Bust-A-Move 2 for the PlayStation. The game''s Puzzle mode includes a feature that saves initials of those who have completed the level in the fastest time. The game contains a survivor mode where the player has to burst the oncoming bubbles, making sure they don''t reach the bottom line which spells the end of the game. Also present is a vs CPU mode, where the player can compete against a selection of eight characters.' FROM games WHERE igdb_id = 43977 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 43977 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
