INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reader Rabbit Personalized Preschool', 'On June 28, 1999, a personalized version of Reader Rabbit Preschool was released, which added the use of A.D.A.P.T. Learning Technology and the Personalized Learning Center as a second disc. This version is based on Version 2.0, featuring the carnival. In 2000, another version was released, featuring the Treehouse Launcher and the Learning Creations program.' FROM games WHERE igdb_id = 373423 ON CONFLICT (game_id, language_code) DO NOTHING;
