INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball Power', 'Pinball Power (referred to as "Golden Logres" in-game and Japan) is another pinball simulator by LittleWing. A sequel to both Tristan and Crystal Caliburn, the game features three tables based on the Arthurian legends: Camelot, Land''s End and Fisher King. After completing all the missions on one table, the game moves to the next one. A practice mode is available to test the last two tables and prepare to the full game.' FROM games WHERE igdb_id = 43740 ON CONFLICT (game_id, language_code) DO NOTHING;
