INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('noel-3-mission-on-the-line', 107624, '1999-03-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coavog.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4q01.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Noel 3: Mission on the Line', 'Noël 3 - Mission on the Line is the latest game in the Noël series. This time the game is a little different from the previous ones. The gameplay is about using your computer to destroy the terrorist virus and clear the network. To do that the player will use 3 antivirus that Yuka Okano created and to use them the player just have to choose hacking in a square of the network and select them in that square of the network that is infected and after that a bar will appear and pressing the button in the proper time will destroy the virus. Once some parts of the network is clear a video phone event will happen and Yuka Okano or other of the girls will talk to your character and give you more information to advance in the game and clear all the network, here the gameplay is similar to the other Noël games, and in the right panel sometimes a ball of light appear and if the player is quick enough he can click on it and transfer it to the catapult part and when the ball of light shines there click again to ask the girl about that subject and gather more information. The game features an album mode that will be unlocked playing the story mode. Probably this game is the best one in the series.' FROM games WHERE igdb_id = 107624 ON CONFLICT (game_id, language_code) DO NOTHING;
