INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hot-wheels-crash', 74090, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co72n3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr8y0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: Crash!', 'Hot Wheels: Crash! is a Hot Wheels game released for PC in 1999. It was the fifth Hot Wheels video game. The object of the game, as the title states, is to crash cars into buildings and structures in each level in order to earn points, with 100 being the goal. The game includes a total of 12 different vehicles and 25 different levels. There are 3 difficulties, and on each difficulty, there are 6 levels. Once 100 points have been scored on each level on any given difficulty , a 7th level for that difficulty is unlocked, which in turn unlocks a special level afterwards. Once every special level for each difficulty has been fully completed, a final level is unlocked. There were also six downloadable levels available by entering the password "1234", though the downloadable levels are now lost due to the shutdown of the site.' FROM games WHERE igdb_id = 74090 ON CONFLICT (game_id, language_code) DO NOTHING;
