INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lionel-trains-presents-trans-con', 348978, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9yq3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxg13.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lionel Trains Presents: Trans-Con!', 'Lionel Trains Presents: Trans-Con! is an educational game focused on the history surrounding the transcontinental railroad. The player controls either the Union Pacific or Central Pacific railroads, and builds the railroad towards Utah. (Each railroad is a different campaign.) Each campaign is divided up into multiple missions. The usual gameplay in each mission consists of choosing the route for the railroad on a grid to connect one city to the next. There is a set budget for each mission, and exceeding that budget will fail the mission. There are sections of interest on the map, and building your railroad into that section can cause an event to occur. This can be good, bad, or give you a choice. For example, workers might start leaving to go to a local gold mine. The decision is to pay the workers more, get more workers, or force the workers to work harder. These decisions are presented by your loyal advisors: Calamity Jane, Wild Bill Hickok, and Tomahawk Beckwourth. The other section of the game is that someone has stolen the golden spike, and recruited six of the wildest outlaws of the wild west to sabotage your railroad. From time to time, a mission will arise to either deal with sabotage or capture an outlaw. These sections are isometric, and play like an adventure game.' FROM games WHERE igdb_id = 348978 ON CONFLICT (game_id, language_code) DO NOTHING;
