INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Startling Odyssey 1: Blue Evolution', 'A PlayStation remake of the PC Engine-CD JRPG, Startling Odyssey. The story is the same as in the original version, starring Leon Solford, a young warrior and the last in the line of great heroes, who must defeat an ancient evil and save the world. The game''s graphics have been completely redone in high resolution 2D, with enhanced anime-style sequences. Battle system has also been redone, featuring isometric perspective and a system that allows the heroes to learn and level up affinities to various elements.' FROM games WHERE igdb_id = 63928 ON CONFLICT (game_id, language_code) DO NOTHING;
