INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '360: Three Sixty', 'RACING and SHOOT-EM UP ACTION in a world submerged beneath oceans of water. Mount your hoverbike and lay waste to your opponents with lethal weapons and a revolutionary firing system. Use everything you have to speed, dodge, and blast your way to the ultimate goal - survival. 360... Survival balances on a knife edge.' FROM games WHERE igdb_id = 45318 ON CONFLICT (game_id, language_code) DO NOTHING;
