INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EGA Coloring Book', 'EGA COLORING BOOK is a computer coloring book. It allows children to use over 500 colors and patterns to color the pictures. Children, age 3 and up, will enjoy bringing the pictures to life with color. Very young children will need adult assistance to use this program. EGA COLORING BOOK will only work on EGA or VGA equipped systems. In addition, the display adapter must have at least 128K of display memory. Use of a mouse input device is optional but recommended.' FROM games WHERE igdb_id = 330270 ON CONFLICT (game_id, language_code) DO NOTHING;
