INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-5thmix-time-to-get-down', 79698, '1999-09-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2c7y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8dzh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania 5thMix: Time to Get Down', 'beatmania 5thMIX is a rhythm game developed by Konami. It is the fifth numbered game in the beatmania series (but 6th beatmania arcade game) and is part of the BEMANI franchise. The game is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. beatmania 5thMIX removed the combo count added in 3rdMIX, and restricted the flashing great judgement to EXPERT mode, both of these changes are reverted in the next entry in the series. Song selection has been reworked and are now shown in a list with difficulty levels shown to the left of the song name. For the first time in the series a harder version of a chart is added. Only 4 songs feature them and the can only be played on stage 2 in Hard mode. The Modifiers SUDDEN and HI-SPEED were added. The song list has 19 songs returning from 4thMIX, 7 Dancemania licenses and 18 new songs. The total track list contains 34 songs.' FROM games WHERE igdb_id = 79698 ON CONFLICT (game_id, language_code) DO NOTHING;
