INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperLite 1500 Series Angolmois ''99', '"Angolmois99" is an addictive simple card game based on the prophecy of Nostradamus and includes real-life parody. Users become the earth''s representative and compete against the Angolmois Four in card games that will decide the destiny of the planet. Luck, insight, intuition and split-second strategic judgement will determine who is the winner. Get ready for the game!' FROM games WHERE igdb_id = 382540 ON CONFLICT (game_id, language_code) DO NOTHING;
