INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Babe and Friends: Animated Preschool Adventure', 'Babe and Friends: Animated Preschool Adventure (aka Babe und seine Freunde: Ein Abenteuer für Kinder im Vorschualter, Babe y sus amigos: Aventuras para los más pequeños) is a video game published in 1999 on Windows by TDK Recording Media Europe S.A.. It''s an adventure and educational game, set in a math / logic and pre-school / toddler themes, and was also released on Mac.' FROM games WHERE igdb_id = 316923 ON CONFLICT (game_id, language_code) DO NOTHING;
