INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr Goo', 'Dr Goo Dr Goo is the first in a series of three 2D platform game. The player controls a Dr Goo - green, intelligent slime thing on a mission to get five medicine boxes in each level in order to save ''lil Jimmy''s life. On the way he has to negotiate multiple hazards including rolling barrels and shark infested waters.' FROM games WHERE igdb_id = 333706 ON CONFLICT (game_id, language_code) DO NOTHING;
