INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fengse-huanxiang', 94939, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yg2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3zc6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fengse Huanxiang', '**This game is playable in Chinese only** Once the Earth was inhabited by gods. But as the human race came into the world, the gods decided to leave the Earth, and only three goddesses were left in charge. Under their guidance, the humans developed their science and technology. But the greedy humans did not accept the superiority of the goddesses, and rebelled against them. Since then, the humans find themselves in a continuous war with gods, demons, dragons, and other races. Over a thousand years later, a young girl named Lufia becomes a treasure hunter. She and her friend Anjieni accept missions all over the world, hoping to earn money and to find the ultimate magic spell. Once they received an assignment to fight against a group of pirates. This was just the beginning of a grand adventure during which Lufia will meet people who were directly involved in the great cosmic struggle many years ago...' FROM games WHERE igdb_id = 94939 ON CONFLICT (game_id, language_code) DO NOTHING;
