INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gachaga Champ', 'Gachaga Champ is an arcade Bishi Bashi game released on 1999 exclusively in Japan. It was developed and published by Konami. Two joysticks to compete in a wide variety of challenges. Players can take the challenge solo or go head to head with another player. Over 40 fun and addictive mini-games, it’s a great fun for both children and adults!' FROM games WHERE igdb_id = 257308 ON CONFLICT (game_id, language_code) DO NOTHING;
