INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Memories Off', 'Memories Off is a visual novel. Most of the game consists of text superimposed on still anime-style visuals. The interaction is restricted to occasional choices the player must make when prompted by the story development. Depending on these decisions the plot may advance into any of the six distinct branches, leading to different endings.' FROM games WHERE igdb_id = 68243 ON CONFLICT (game_id, language_code) DO NOTHING;
