INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nba-courtside-2-featuring-kobe-bryant', 3549, '1999-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gnk.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Courtside 2 Featuring Kobe Bryant', 'NBA Courtside 2 Featuring Kobe Bryant is the sequel to Kobe Bryant in NBA Courtside and features NBA star Kobe Bryant on its cover. Bryant also performed the motion capture for the game. The ability to play multiple seasons has been added. New features include the ability to play a three-point contest and additional options for creating a player from scratch. The game features improved artificial intelligence helps to improve the realism of the gameplay. New dunk styles are possible to implement and enhanced motion capturing allows the no-look pass to be used during gameplay. There are more than 300 players and games can either be a realistic simulation of actual NBA action or a full-blown arcade experience. Plays such as the isolation play, the post up, and the triangle offense can be called.' FROM games WHERE igdb_id = 3549 ON CONFLICT (game_id, language_code) DO NOTHING;
