INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New Robinson', 'New Robinson is a 2D point-and-click adventure game inspired by Daniel Defoe''s Robinson Crusoe. After a shipwreck, the player must solve puzzles to address survival needs including water, food, fire, and shelter while encountering wildlife, natives, and an abandoned ship. The player rescues a companion named Friday and works toward escaping the island by constructing a balloon while avoiding pirates. The game allows interaction with items on any active screen object and includes multiple mini-games.' FROM games WHERE igdb_id = 117319 ON CONFLICT (game_id, language_code) DO NOTHING;
