INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('thrasher-presents-skate-and-destroy', 44916, '1999-11-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2roq.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thrasher Presents: Skate and Destroy', 'Tour the world and ride open and interactive terrain through 12 levels of real-world skate spots from your hometown to New York, Los Angeles, San Francisco and international hotspots in the UK and Germany. The open-nature of the courses allow for constant mixing up of tricks on the quest to find the perfect line. Choose from six different fictional skaters with varying degrees of strength and weakness. For a tough and versatile skater, choose Axl or for a more balanced skater take Kahli on your mission. Each skater features their own skating and clothing style. Although each skater offers a different and varying skill level, their mission objectives are the same. Each player starts off as a wanna-be amateur skater with no sponsor or street credibility. Your goal is to turn your skater into the Thrasher Magazine Skater of the Year.' FROM games WHERE igdb_id = 44916 ON CONFLICT (game_id, language_code) DO NOTHING;
