INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tall Infinity', 'Tall Infinity is a single-player puzzle game where users manipulate multi-colored blocks to construct a tower. The main game consists of eight stages, with players needing to complete ten floors of the tower to pass each stage. Players must avoid unnecessary moves or risk losing the game. There are three difficulty levels, and two additional game modes: time attack and endless play.' FROM games WHERE igdb_id = 45062 ON CONFLICT (game_id, language_code) DO NOTHING;
