INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-4thmix-the-beat-goes-on', 70632, '1999-04-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2c40.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8dpv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania 4thMix: The Beat Goes On', 'beatmania 4thMIX is a rhythm game developed by Konami. It is the fourth numbered game in the beatmania series (but 5th beatmania arcade game) and is part of the BEMANI franchise. The game is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. beatmania 4thMIX is the first big redesign of the series, it features a brand new interface. Difficulty is now on a scale from 1 to 7. All songs have been given a single and double mode chart. Song list shows not only genre and title, but artist as well. Although all previous beatmania songs have been removed. a brand-new set of 23 songs was added as a replacement. It is the first time that licensed songs makes an appearance in the series, as well as crossovers from other BEMANI games.' FROM games WHERE igdb_id = 70632 ON CONFLICT (game_id, language_code) DO NOTHING;
