INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman Dash 2: Episode 1 - Roll-chan Kiki Ippatsu! no Maki', 'Included with the release of Tron ni Kobun, this game is a technical demo that serves as a prelude to Rockman Dash 2: Episode 2 - Ooinaru Isan (Mega Man Legends 2). These four missions precede the events of Episode 2, which made up the entirety of Mega Man Legends 2 for versions outside of Japan, though they are mentioned in the later game''s dialogue.' FROM games WHERE igdb_id = 234973 ON CONFLICT (game_id, language_code) DO NOTHING;
