INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cookie''s Bustle', 'Cookie''s Bustle is an adventure game in which the player guides Cookie throughout Dero City to guide her towards her goal of competing in the sports competition. The control scheme is very simple; Cookie moves on her own to follow the cursor wherever it''s pointed on screen, and most actions can be taken by positioning her without clicking on anything. Once she actually enters the tournament, there are minigames for each of the sports.' FROM games WHERE igdb_id = 122887 ON CONFLICT (game_id, language_code) DO NOTHING;
