INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snowmobile-championship-2000', 70325, '1999-10-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3knf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sccqbb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snowmobile Championship 2000', 'In Snowmobile Championship 2000, a bargain-bin snowmobile racing game from GT Interactive, you get to race against four other AI drivers in one of eight locations. The races take place in some of the world’s most beautiful winter settings, including the Canadian Rockies, Minnesota Lake, Iowa Farmland, Maine Forest, Yellowstone Park, Scottish Highlands, German Village, and Japanese Field. Varied terrain elements present challenges and opportunities, including Moguls, Ice, Mud, and Turns. How you take a turn, or whether you choose to ski over the moguls or choose a landlocked course around them, are all bits of strategy that can move you to the front of the pack, or send you to last place depending on your skill. You can either compete in the official “Race” mode, or enter the “Practice” mode which lets you improve your skills on any of the eight different tracks. Game controls are all keyboard based. Up Arrow to accelerate, Right Arrow to turn to the right, Left Arrow to turn to the left. Brake or Stop just by lifting your finger off the accelerator key. Options are available to modify your point of view (3rd person far, 3rd person close-up, and 1st person), resolution (up to 640x480), and level of detail (low, medium, or high). You can also toggle on/off the digital statistics (time, lap indicator, and speed) on the HUD.' FROM games WHERE igdb_id = 70325 ON CONFLICT (game_id, language_code) DO NOTHING;
