INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chocobo Stallion', 'A Japan-only game centering around the Chocobos. The game was inspired by the Chocobo racing minigame at the Gold Saucer in Final Fantasy VII. The racing gameplay is similar, but has its own independent story that is not related to Final Fantasy VII. The player must train a chocobo and race against other computer controlled chocobos.' FROM games WHERE igdb_id = 22897 ON CONFLICT (game_id, language_code) DO NOTHING;
