INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('konung-legend-of-the-north', 10492, '1999-09-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ayl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvod.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konung: Legend of the North', 'Konung is a good old days RPG with some RTS and Adventure elements. In contradiction to Diablo-like games, Konung goes beyond action-style role-playing and offers adventure-style gameplay with dozens of non-linear quests and strong storyline set in the complex atmosphere of VII-century Scandinavia, the mystical “Land of the North”. Konung features the most attractive RTS elements, including settlement management. The player has the opportunity to seize settlements, manage their resources and build various constructions and installations, enjoying the best of RTS elements. The world of Konung is a unique and spacious fantasy land that combines parts of known history with classical myths and the legends of the Chronicles, including immortal heroes, magical artefacts and ancient sorcery. The whole world is shaped by three cultures on the verge of the second millennium: tribes of wild Slavic hunters, noble traders of the still-powerful Byzantine Empire, and fearless Viking warriors.' FROM games WHERE igdb_id = 10492 ON CONFLICT (game_id, language_code) DO NOTHING;
