INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Puzzle Bobble', 'Super Puzzle Bobble (スーパーパズルボブル Sūpā Pazuru Boburu) is an arcade puzzle game in the Puzzle Bobble series developed by Taito and released in 1999. Super Puzzle Bobble''s gameplay is relatively the same as previous entries. However, it introduces several new features and elements to the series. These include smaller bubbles for the player to hit small areas, big bubbles which change every bubble color in the level to itself, and blocks which can move the pointer to different areas on the board.' FROM games WHERE igdb_id = 138063 ON CONFLICT (game_id, language_code) DO NOTHING;
