INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arthur''s 1st Grade', 'Arthur''s 1st Grade was originally released as a two disk video game centered around a Bionic Bunny Contest, which Arthur and his friends are trying to win in the game by helping people. The first disk is called "Bionic Bunny''s Contest," and the second is called "Activity Center," which allowed players to print off coloring pages and create their own songs. This release was for Windows 95/98, but the game has since been added to Steam.' FROM games WHERE igdb_id = 70988 ON CONFLICT (game_id, language_code) DO NOTHING;
