INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guitar Jam', 'Namco arcade cabinet released in 1999, only in Japan. Distinctive for its guitar-centric gameplay and controller, Namco was sued by Konami over its striking similarities to GuitarFreaks and most cabinets were converted. It is considered extremely rare to find an unaltered Guitar Jam cabinet in the modern-day, much less a working one.' FROM games WHERE igdb_id = 266894 ON CONFLICT (game_id, language_code) DO NOTHING;
