INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cool Bricks', 'Cool Bricks is a puzzle game that requires the player to use a bat to guide a ball to break bricks to progress. Compared to Breakout, Cool Bricks features the inclusion of varied weapons, such as laser guns, missiles, grenade launchers, larger bats or multiple balls, and the addition of power-ups with positive and negative effects, such as a ''poison mode'' that creates involuntary player movement. The game features 160 levels with a password system to allow for returning to certain stages.' FROM games WHERE igdb_id = 50032 ON CONFLICT (game_id, language_code) DO NOTHING;
