INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Landing High Japan', 'Landing High Japan is an arcade game in which the object is to pilot a commercial airliner, taking off from and landing at several Japanese airports.[3] It is a part of the Landing series of airline simulation arcade games which also includes Midnight Landing (1987), Top Landing (1988) and Landing Gear (1995).  The game is available in both 29" and 50" versions.' FROM games WHERE igdb_id = 129142 ON CONFLICT (game_id, language_code) DO NOTHING;
