INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zebco-fishing', 49979, '1999-09-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u74.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zebco Fishing!', 'You are out on the lake, and everything is quiet. Suddenly, a fish hits your lure. The fish pulls the line while you fight it, trying to reel it in. It dives deep and flies out of the water; you give the line some slack, and then reel it in. Eventually, the fish loses this fight. You can have this kind of excitement with ZEBCO FISHING! for the Game Boy Color. Hit one of two lakes with a choice of 11 different fishing lures. Try to catch the biggest bass possible in the Tournament mode, and for an extra challenge, try to catch exactly 21 pounds of bass in the Blackjack Bass mode. In both modes, catching fish other than bass has no effect on the outcome. Try to become a fishing champion with ZEBCO FISHING!' FROM games WHERE igdb_id = 49979 ON CONFLICT (game_id, language_code) DO NOTHING;
