INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Miniverse Minigolf', 'Two 9 hole mini golf courses for 1-4 players. One course is set on "Earth" and features putting through locations such as a construction site, a war zone, and a casino. The other course is set in space and includes a variety of science fiction obstacles like teleporters and laser shields.  Players can choose to control their putter by pushing or pulling the mouse and can select one of several different colors for their golf ball.' FROM games WHERE igdb_id = 93383 ON CONFLICT (game_id, language_code) DO NOTHING;
