INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lexis', 'This is similar to the game Tetris but instead of falling blocks, you have to make words out of falling letters. Some words will give you cheats or unlock a bonus game. Keep going until the letters reach the top of the screen, at which point the game is over. Words can be formed horizontally, vertically, forwards or backwards.' FROM games WHERE igdb_id = 40859 ON CONFLICT (game_id, language_code) DO NOTHING;
