INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'K.S.-n-Kickin', 'K.S.-n-Kickin is a 3D action puzzle video game made by Artworld UK and Big Future Ltd. for Kinder Surprise, with music licensed from Telstar Records. It was released for Microsoft Windows. The game was a promotion by Ferrero to "strengthen their foothold in the younger age group market". The game features Kinder Surprise toys from the K00 series. The game was not sold in stores, but was offered in exchange for Kinder Egg wrappers which were sent to Ferrero. The promotion was advertised via TV commercials. K.S.-n-Kickin has the same map layout and soundtrack as Gubble 2 (part of the Gubble video game series), but has different backgrounds, characters, and items.' FROM games WHERE igdb_id = 265977 ON CONFLICT (game_id, language_code) DO NOTHING;
