INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Worldwide Soccer 2000', 'Sega and Silicon Dreams are on the ball to bring Sega WorldWide Soccer 2000 to Dreamcast. The beautiful game is brought to life in this fast action packed soccer simulation. Put on your old school kit and challenge all your friends - (up to four people can play). Sega WorldWide Soccer 2000 - miss out on this and you will be as sick as a parrot. Pick it up on a transfer and you will be over the moon.' FROM games WHERE igdb_id = 45790 ON CONFLICT (game_id, language_code) DO NOTHING;
