INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tarde Animada', 'Join the funniest gang on the Internet and spend an afternoon playing with super cool characters! Tarde Animada mixes an adventure game with various kinds of games. Have fun wandering around the Bugigangue club! Commanding Gustavinho, you meet all the characters, talk to all of them, and choose who you want to play with! It''s like spending an afternoon with your Bugigangue friends! Each of them has a different game! You can play target shooting, penalty shootout, cook, mad scientist, and much more!' FROM games WHERE igdb_id = 296113 ON CONFLICT (game_id, language_code) DO NOTHING;
