INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cythera', 'Cythera is an RPG that could be described as the Ultima of the Macintosh, as it focuses on immersion and interactivity, just like the DOS classic Ultima VII. It features single-character world exploration, a high degree of interactivity with objects in the environment, a hunger system, and keyword-based dialogues.' FROM games WHERE igdb_id = 131044 ON CONFLICT (game_id, language_code) DO NOTHING;
