INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Arcade Frenzy', 'This is a set of four arcade games based on Disney animated films. In Rooftop Ruckus, players race across the rooftops of Agrabah from Aladdin, moving Abu strategically past windows to light up the darkened city. Mu Shoot is based on the film Mulan and has players defending a village by shooting off fireworks at the advancing Huns. Two more arcade games are offered based on Hercules and The Little Mermaid.' FROM games WHERE igdb_id = 120809 ON CONFLICT (game_id, language_code) DO NOTHING;
