INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('renegade-racers', 44978, '1999-12-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coabdb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar41q5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Renegade Racers', 'Renegade Racers, a watercraft racing game, has three game modes including arcade, quick race and high score. The modes are further broken down into eight race modes of varying types. In Battle Race, you blast opponents during the race while Check Point Challenge requires reaching checkpoints within pre-set parameters. Other self-explanatory races include Smash & Grab, Treasure Hunt, Head-to-Head and Dodgems. Rounding out the modes are the precision events Air Time and Drop Zone. The game features three difficulty choices, each with a different number of levels. At the easy setting there are 32 levels while the medium and hard settings have 40 and 48 levels respectively. In arcade mode, you must face increasingly difficult challenges as you complete the levels by meeting pre-determined times, tasks and finish-position parameters. As you complete various levels, a head-to-head challenge mode allows you to race against level bosses, unlocking the race for use in other play modes.' FROM games WHERE igdb_id = 44978 ON CONFLICT (game_id, language_code) DO NOTHING;
