INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('simple-1500-series-vol-20-the-puzzle', 203007, '1999-11-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4sue.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch6fq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 20: The Puzzle', 'Is a classic 2D puzzle game with a fantasy theme and cartoon graphics. The gameplay as usual in these kind of games is about putting the same kind of colour ball pieces together so they can be destroyed. When all the colour ball are destroyed the level is cleared. The major difference is in how the balls are moved, the player controls a character that is on charge of somekind of cannonball that used to shot the different colour balls, the more the button is pressed the farther the ball will go.' FROM games WHERE igdb_id = 203007 ON CONFLICT (game_id, language_code) DO NOTHING;
