INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('air-strike', 41481, '1999-01-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1pfb.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Strike', '[Unfinished 1982] You''re piloting a biplane through enemy territory. Drop bombs on factories and ammunition depots. Engage enemy planes in dogfights to the death!  Due to the popularity (especially with APh and Mattel programmers) of the Biplanes game in the Triple Action cartridge, APh proposed this one-player version. A prototype was shown to Mattel with scrolling mountain terrain and targets that could be bombed. The plane graphics, sound effects and flight control were lifted directly from Biplanes. (Enemy planes, which would have presented an artificial intelligence-programming challenge, were not included in the prototype but promised for the finished game.)  Marketing (not as crazy about Biplanes as the programmers) chose not to release the game and it went unfinished.  FUN FACT: A nice touch is that the second you lose control and smash into the side of a mountain, another biplane flies on-screen, cheerfully circling the crash site, trailing a banner displaying your score.' FROM games WHERE igdb_id = 41481 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 41481 AND p.igdb_id = 67 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mystic-ark-maboroshi-gekijo', 67326, '1999-03-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8kyn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sck7qu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystic Ark: Maboroshi Gekijo', 'Sequel to Mystic Ark from the SNES. This is a pure adventure game, shedding all the JRPG elements the series had up to that point, eliminating all random encounters, making combat an afterthought, and uses the Arks in two iterations for solving puzzles: their Fairy Form and fully awakened Ark Form. They can utilize their powers through cards which can be found or won through games which you''ll need to activate different powers from elemental abilities to manipulating a character''s thoughts, changing their mind by making them braver or changing their perspective, etc. Subtle differences aside, the rest of the gameplay is fairly standard and includes using items and interacting with objects to progress.' FROM games WHERE igdb_id = 67326 ON CONFLICT (game_id, language_code) DO NOTHING;
