INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-for-wonderswan', 135089, '1999-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co964i.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania for WonderSwan', 'A portable version of Konami''s Beatmania series. The game features falling blocks that you must hit in time with the beat when they reach the judgement line. The game is played with the Wonderswan held vertically. A scratch attachment is included that you mount on the console to be able to trigger the scratch button more easily. Unlike the Game Boy versions of Beatmania, beatmania for WonderSwan features the original versions of the songs, instead of 8-bit renditions. The game is played in rounds, with each round giving you a selection of songs, as you clear the round a new selection with harder songs is made available. There are 11 songs included in the game.' FROM games WHERE igdb_id = 135089 ON CONFLICT (game_id, language_code) DO NOTHING;
