INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('scrabble-crossword-game', 45054, '1999-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7rb4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqkzp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scrabble: Crossword Game', 'Hasbro Interactive''s best-selling computer title based on one of the world''s most famous word games has made the translation to the PlayStation with real-time 3D graphics and support for up to four players. As with the two previous CD-ROM games, Scrabble for the PlayStation even contains the Merriam Webster''s Official Scrabble Player''s Dictionary, 3rd Edition, so players can look up definitions to certain words (not all are available, however) and determine if a word actually exists. For those unfamiliar with the board game from which this title is based, Scrabble involves forming words using wooden tiles representing individual letters. These tiles are then placed into rows on a board made up of 225 spaces. Each letter is worth a certain point value, and some of the spaces will offer specific bonuses if you manage to build off them. The player with the most points after all the tiles have been placed on the board is considered the winner. The PlayStation version follows this same format, but with automatic scoring and a computer opponent named Maven with eight selectable difficulty levels.' FROM games WHERE igdb_id = 45054 ON CONFLICT (game_id, language_code) DO NOTHING;
