INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hugo: Scylla''s Revenge', 'Hugo: Scylla''s Revenge (international title) is a PC-only video game originally developed by Krogh Mortensen Animation and published by ITE Media in 1999. It is the third of Hugo Christmas special games ("Wintergames"), the other ones being Winter Games and Hugo Saves Christmas.' FROM games WHERE igdb_id = 230588 ON CONFLICT (game_id, language_code) DO NOTHING;
