INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dancing Furby', 'Dancing Furby is a Japanese only rhythm game released for the Game Boy Color. The gameplay is similar to games like Dance Dance Revolution in which you press the inputs displayed with the correct timing. In addition the game includes multiple mini-games, a song creator, cooperative multiplayer and song sharing, and functionality to interact with actual owned Furbys.' FROM games WHERE igdb_id = 85717 ON CONFLICT (game_id, language_code) DO NOTHING;
