INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aguante Imaginario', 'Aguante Imaginario is a puzzle-based game about a strange world full of eccentric and unique people. The game consists of six arcade games that vary from a jigsaw to riddles, putting emphasis on memorization and reflexes. The game can also be played with two players, leading to competitive gameplay.' FROM games WHERE igdb_id = 107240 ON CONFLICT (game_id, language_code) DO NOTHING;
