INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oscarzinho e o Bug do Esporte', 'Oscarzinho e o Bug do Esporte is a kids'' adventure game where Oscarzinho, based on the Brazilian basketball player Oscar Schmidt, and his friends need to deal with a group named Drugs that have infested the planet with a computer virus and wiped out all memory of sports and to revert this situation, they will challenge the Drugs until they manage to make all sports practiced again. The game aims to encourage the practice of sports, teach citizenship notions, show the dangers of drug use, and develop the player''s creative potential and motor coordination.' FROM games WHERE igdb_id = 218411 ON CONFLICT (game_id, language_code) DO NOTHING;
