INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1 on 1 Government', '1 on 1 Government is a 3D street basketball game developed and released by Jorudan (in conjunction with Tecmo) for arcades exclusively in Japan. The sequel to the original PS1 game 1 on 1, Government adds a new two-on-two game mode (known as "2 on 2") and two additional playable characters (with all characters unlocked from the start).' FROM games WHERE igdb_id = 39809 ON CONFLICT (game_id, language_code) DO NOTHING;
