INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aquanaut''s Holiday 2', 'Aquanaut''s Holiday 2 is the sequel to Aquanaut''s Holiday. Like in its predecessor, the player takes control of a submersible in order to explore the sea depths and discover a variety of animal species. Contrary to the first game''s only area, the sequel has many different areas following different themes to explore.' FROM games WHERE igdb_id = 106041 ON CONFLICT (game_id, language_code) DO NOTHING;
