INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pets-fun-house', 90466, '1999-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobkep.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vpetd2skobcanfxq5hgz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pets Fun House', 'Traverse a map of an ancient land and solve plenty of puzzles on the way. Control the chameleon idol and, using its magic power, blast gems before they reach the hole. At the end of each level, the score is converted to money that you can spend at the shop to buy extra lives or new skins for the chameleon. Each skin comes with different powerups and effects. Catch a boatload of fishy fun in this original arcade challenge! Load up the RV and crisscross the country in a series of tournaments that will put your angling prowess to the test. Cast your line in colorful locations like Bullhorn Lake, Golden Corn Lake, and Wicked Mansion Lake. Catch fish to earn points and climb to the top of the rankings in the amateur, pro, and elite circuits. Your fellow fishers are sure to keep you on your toes, but watch out for surprises swimming just below the surface that will slow you down. Featuring innovative gameplay, colorful full-screen graphics, and hours of fun for the whole family, Fishing Craze is no fish-tale, it''s the real thing! Catch it today! Breed baby animals and nurture their growth inside an amusing pet shop. As a boutique owner, you must work hard while maintaining a great sense of humor. Raise eight kinds of animals to make healthy, vivacious pets for loving owners. Buy appropriate items for particular breeds and work to unlock all items in the shop`s interior. Check the pet sales report frequently to be a smart business owner, and build the Pets Fun House empire. Help amazing toy robot Xango find his upgrade parts in this brain-stretching, 3D animated action puzzler adventure. Three game modes guarantee many hours of action, puzzling and relaxing fun. Match three colored crates and watch ‘em explode in Classic mode. Solve brain-twisting puzzles in Puzzle mode. Play without time pressure in Relax mode. Exotic landscapes, lively tango music and wacky dances make Xango Tango fun for the whole family. Help Xango find all of his parts to see the surprise ending!' FROM games WHERE igdb_id = 90466 ON CONFLICT (game_id, language_code) DO NOTHING;
