INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Frog Frenzy', 'Meet Froggy. He''s cute, he''s cool, and he''s the only frog alive who can''t swim! Worse yet, a crazy French chef who is trying to make a frog legs dinner is chasing Froggy! Help Froggy escape by hopping through highways while trying to avoid traffic and travelling across rivers without drowning in the water. It is a tough job with many surprises along the way. The challenge is yours; get Froggy home to safety!' FROM games WHERE igdb_id = 47046 ON CONFLICT (game_id, language_code) DO NOTHING;
