INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anxious: Yuukyuu no Memory', 'Near future. Technology advances have allowed to create a perfect artificial lover indistinguishable from real women. Main character gets a job to test four such robots every day. He understands those are robots, but can''t help having feelings for them.' FROM games WHERE igdb_id = 278021 ON CONFLICT (game_id, language_code) DO NOTHING;
