INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Galaxy Fighters', 'In 3D Galaxy Fighters (strongly inspired by the classic Galaga series), your mission is to defend the galaxy from hordes of intergalactic invaders, which appear from the sides of the screen waves. Your ship can only withstand one hit, but you can upgrade your weapons as you destroy enemies. These upgraded weapons have their own benefits and problems, and have limited ammunition.' FROM games WHERE igdb_id = 205839 ON CONFLICT (game_id, language_code) DO NOTHING;
