INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zen-Nippon Pro Wrestling: Ouja no Tamashii', 'Zen-Nippon Pro Wrestling: Soul of Champions is a 3D Japanese wrestling game that features 25 wrestlers (including one hidden wrestler) from the All Japan Pro Wrestling promotion. There are seven modes of play available in the game: One Night Match, Champion Carnival, Real World Tag League, Battle Royal, Create Edit (Create-a-Wrestler), MVP Season Mode, and Defend Title (hidden mode).' FROM games WHERE igdb_id = 45073 ON CONFLICT (game_id, language_code) DO NOTHING;
