INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-complete-mix', 94744, '1999-01-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2c3f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8dnu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'beatmania complete MIX', 'beatmania completeMIX is a rhythm game developed by Konami. It is the fourth game in the beatmania series and is part of the BEMANI franchise. The game is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. Even though the game is based on the beatmania 3rdMIX engine, it does not feature a combo count. It is the first game in the series to show song titles on the song select and not just the genres. The flashing great judgement is introduced, which requires better precision to obtain over the normal great judgement. INTERNET RANKING functionality is implemented. After a course has been completed an INTERNET RANKING code was given, which could be entered on Konamis online leaderboards. beatmania completeMIX is a compilation mix containing the full song lists from beatmania - beatmania 3rdMIX. Only 4 new songs are added to the game, 2 of which are english versions of earlier songs. The total number of songs available in the game is 44.' FROM games WHERE igdb_id = 94744 ON CONFLICT (game_id, language_code) DO NOTHING;
