INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mtv-music-generator', 45098, '1999-11-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7xwu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scrd6b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MTV Music Generator', 'There are music-mixing computer programs that cost thousands of dollars, but none of them are this fun. You chose your rhythm tracks, bass lines, guitar riffs, and triangle hits in this complete music-making experience. You can make rock, pop, hip-hop, techno, or jazz songs, and each will be vastly different from the others. There are more than 1,500 riffs and 3,000 instrument sounds to choose from, and you can even write your own parts instead of using the pre-programmed melodies. Just about everything you can think of can be manipulated here, right down to the volume of the floor toms, the amount of reverb applied to each instrument, and the song''s tempo. The next step is to create a music video for your masterpiece, and you''ll have plenty of 3D clips at your disposal in so doing. Once you have your complete package, you can save everything to a memory card and access any part of it (from an instrument sound or keyboard riff to the entire song) later. All in all, it''s about the most creative use of a video game console imaginable.' FROM games WHERE igdb_id = 45098 ON CONFLICT (game_id, language_code) DO NOTHING;
