INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gallop Racer', 'Gallop Racer (known as "Gallop Racer 3: One and Only Road to Victory" in Japan) is part horse racing simulation, part action/arcade racer. When choosing horses for your stable, you have to take a lot of factors into account. For instance, is the horse a long or short distance runner? Does it do better on a dry track or a wet track? The factors appear to be endless at first.' FROM games WHERE igdb_id = 13659 ON CONFLICT (game_id, language_code) DO NOTHING;
