INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ramenbashi', 'Kotobuki Hidezo, a soldier returning to Tokyo learns that his father has passed away, and he carries on his legacy by running the family ramen shop. Play as Hidezo over the course of half a century as he serves ramen to his many and often troubled customers in the heart of post-war Tokyo.' FROM games WHERE igdb_id = 92513 ON CONFLICT (game_id, language_code) DO NOTHING;
