INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Chinese Fighter EX', 'Super Chinese Fighter EX is a fighting video game for the Game Boy Color released by Culture Brain in 1999. It is part of the Super Chinese series and is the final Fighter game in the series. Unlike most of the Super Chinese games, Fighter EX is not an action game or role-playing video game. The game features several characters from the Super Chinese series, including the main characters, Jack and Ryu.' FROM games WHERE igdb_id = 50557 ON CONFLICT (game_id, language_code) DO NOTHING;
