INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'T-Zer0', 'T-Zer0 (formerly Trauma Zero) is an arcade, side scrolling, shooter with a sci-fi theme. The game is AGA (over 256 colour graphics), scrolls at 50hz with a 2-player coop option, featuring a choice of three ships to control, two main gameplay routes with collectibles, power-ups and enemies to defeat.' FROM games WHERE igdb_id = 69588 ON CONFLICT (game_id, language_code) DO NOTHING;
