INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zelda Classic', 'Zelda Classic is an unofficial open-source Zelda fan game and game engine. It is, by itself, a recreation of the original The Legend of Zelda, but it allows the creation of expansions (called quests) which can be played with the game engine.' FROM games WHERE igdb_id = 135127 ON CONFLICT (game_id, language_code) DO NOTHING;
