INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Majokko Daisakusen: Little Witching Mischiefs', 'Majokko Daisakusen is a turn-based strategy game with action-style battles featuring characters from several famous magical girl anime series from the ''60s, ''70s, and ''80s: Mahō Tsukai Sally, Himitsu no Akko-chan, Mahō Tsukai Chappy, Cutey Honey, Majokko Megu-chan, Hana no Ko Lunlun, and Mahō Shōjo Lalabel. It is in fact a reworked version of The Unholy War with all of the graphics, sound, and story completely replaced. The game itself, however, is essentially identical between the two releases.' FROM games WHERE igdb_id = 122570 ON CONFLICT (game_id, language_code) DO NOTHING;
