INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop''n Tanks', 'Pop''n Tanks! is a 1999 Japanese video game released for the PlayStation. It was developed by Symbio Systems and published by Enix. The game was directed by Jun Matsumoto, while manga artist Mine Yoshizaki provided character designs. The game is a tank combat game, featuring one on one battles between tanks. The game has never been released outside of Japan.' FROM games WHERE igdb_id = 43801 ON CONFLICT (game_id, language_code) DO NOTHING;
