INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aironauts', 'Aironauts is a flying aerobatic stunt action game for up to two players, set in a dystopian future society where prisoners are pitted against one another in arena battles to the death. Players choose from 8 characters, each with distinct weapons and looks, and take to the skies in a battle to the death for the viewing public on "SKP-TV". Every level, called battle area, consists of a series of challenges, e.g. destroying certain items or a checkpoint race, ended with a one-to-one boss fight. After every area the player can trade collected and earned angel wings for power-ups which improve his abilities, e.g. speed or armor. The game features Deathmatch, Stunt and Battle Modes.' FROM games WHERE igdb_id = 43750 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 43750 AND p.igdb_id = 7 ON CONFLICT DO NOTHING;
