INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medarot R', 'Medarot R is the Playstation One remake of the classic Gameboy game and is the very first Medarot game that was released in full-3D graphics for the Sony PlayStation console, featuring, for the very first time, works from Kenki Fujioka. It was developed by Imagineer and published by Natsume. The gameplay is about going around the town meeting different characters and winning the battles to upgrade your Medarot and advance through the game.' FROM games WHERE igdb_id = 92425 ON CONFLICT (game_id, language_code) DO NOTHING;
