INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie as Sleeping Beauty', 'Barbie as Sleeping Beauty tells the story of Princess Rose, who was gifted with beauty, laughter and love by good fairies, but cursed by an evil fairy to fall asleep for one hundred years before her 16th birthday. Help Princess Rose get ready for her 16th birthday party, wake up her animal friends, design a crown and dress to wear to the party, and find the hidden fairies in the library to get the key to the banquet hall.' FROM games WHERE igdb_id = 200605 ON CONFLICT (game_id, language_code) DO NOTHING;
