INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania Append Gottamix', 'Is a derivative game from beatmania series. It has a total of 20 songs, most of them brand new songs. It requires a Key Disc to play it because it''s an extension. Normal, Hard and Expert are absent from the game. The player go straight to play the songs.' FROM games WHERE igdb_id = 83017 ON CONFLICT (game_id, language_code) DO NOTHING;
