INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brickout!', '[Unreleased 1981]  GAME DESCRIPTION  Use your paddle to bounce a ball against descending rows of colored bricks. Hit bricks disappear, scoring points.  PRODUCTION HISTORY  Brickout! was an Intellivision version of the Atari arcade and video game Breakout. It was intended for the Triple Action cartridge, which was originally to have included five arcade-type games. Brickout! was shelved for fear of legal action from Atari; such fears also killed the original version of Astrosmash, which was an Asteroids-like game.' FROM games WHERE igdb_id = 41441 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 41441 AND p.igdb_id = 67 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moremore', 39953, '1999-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hzc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scii20.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MoreMore', 'Semicom''s second pure mini game collection relies on quick and simple challenges in the same vein as Bishi Bashi, borrowing its input scheme of three colored buttons. Seventeen games in four tears wait for their completion, ranging from boring stuff like "find the differing image" or "choose the right exit from the labyrinth", to more inventive tasks where the player evades Gozilla''s stomping feet or performs magic tricks in form of button combinations. The presentation is nothing to write home about. Everything looks distinctively low budget, especially the narrow color range leaves a rather weird impression.' FROM games WHERE igdb_id = 39953 ON CONFLICT (game_id, language_code) DO NOTHING;
