INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moon Whistle', 'Moon Whistle is a Japanese language freeware role-playing video game created with RPG Tsukūru 95. Mainly made by Kōichirō Takaki, also known as Kannazuki Sasuke, this game involves an adventure of a five-year-old kindergartner in a pseudo-Japanese city of the 1980s and 1990s. In 2011 an updated version was released called Moon Whistle XP.' FROM games WHERE igdb_id = 166142 ON CONFLICT (game_id, language_code) DO NOTHING;
