INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blood-lines', 45056, '1999-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/bdkeiw819b8yac4l13js.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood Lines', 'Set in the future, competitive sport is outlawed and becomes the pursuit of an underground network of the world''s greatest athletes. Inspired by the nations of old, they form clans and engage each other in tribal combat to protect the honour of their blood-lines. There can be only one winner. Control one of the clans, and fight to the death in a last-man-standing battle against multiple opponents. The environments allow for roaming and hiding, allowing players to tactically attack and run away to evade attack. Weapons can be found, used and recharged across the arena.' FROM games WHERE igdb_id = 45056 ON CONFLICT (game_id, language_code) DO NOTHING;
