INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Denpa Shonen-teki Kenshoseikatsu Soft Nasubi no Heya', 'Denpa Shonenteki Kenshoseikatsu Soft Nasubi no Heya (電波少年的懸賞生活ソフト なすびの部屋) is a 1999 game by Hudson for the Sega Dreamcast. It ties into a Japanese reality show where a comedian willingly locked himself in a small apartment living off sweepstakes winnings until he won ¥1,000,000 worth of goods.' FROM games WHERE igdb_id = 283472 ON CONFLICT (game_id, language_code) DO NOTHING;
