INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcomage', 'A card-based mini-game from Might and Magic VII and VIII, the popularity of which convinced New World Computing to turn it into a standalone game. It''s a simplified version of Magic the Gathering, where the goal is to destroy the opponent''s tower before they can reciprocate.' FROM games WHERE igdb_id = 70264 ON CONFLICT (game_id, language_code) DO NOTHING;
