INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HyperBowl: Arcade Edition', 'HyperBowl scores just like conventional bowling, but the style of play is entirely unique. In this virtual bowling game, you can steer the ball all the way to the pins! Sound too easy? Not really -- you must dodge trolley cars in San Francisco 2099, leap buses on the streets of Tokyo, navigate across a pitching ship on the High Seas, and avoid whatever other obstacles are thrown your way. Players seeking more predictable play can always fine tune their skills in a Classic bowling alley or bowl through a peaceful Yosemite forest.' FROM games WHERE igdb_id = 73880 ON CONFLICT (game_id, language_code) DO NOTHING;
