INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('large-ponpon', 305064, '1999-11-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8bkd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scso38.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Large PonPon', 'Our hero''s girlfriend, Rurika, suddenly informs him that she is being transferred to Paris. However, after only a few months, she gives up her job and comes home; she is pregnant. Following an extremely hot argument, she leaves him without telling him where she is going. Our hero goes looking for her and learns that she has checked into an obstetrics ward. Here at the hospital, he accidentally runs into Yukari, an old childhood friend from school. He also starts up a hot relationship with a married woman named Touri, who is staying in the next hospital room. His girlfriend really starts to get jealous of his other playmates. Will he fulfill his obligations to Rurika, or will he keep going after hot, new babes? It is 0verflow''s debut work and most characters belong to the core families of 0verflow''s works.' FROM games WHERE igdb_id = 305064 ON CONFLICT (game_id, language_code) DO NOTHING;
