INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 23: The Gateball', 'Simple 1500 Series Vol. 23 - The Gateball is a golf croquet game featuring different teams and also a tutorial explaining the rules of the game. Set in a variety of courses such as gymnasium Park Stadium ground also changes how the ball rolling, try to choose a favorite team and participate in this unique 5 teams each with different characteristics. Us to explain the rules, classroom equipped with a gate ball mode, even beginners can easily enjoy.' FROM games WHERE igdb_id = 203009 ON CONFLICT (game_id, language_code) DO NOTHING;
