INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flame Gunner', 'Flame Gunner is a 3D arcade shooter. The game is very simple - the player (or players) must perform a specific task, usually something around destroying or killing the right amount of enemies. If a player does the job, he will go to the next arena (or on the current arena, a new task will appear). 3 heroes are in the game - Falcon, Talia (she is only female in game) and Kai.' FROM games WHERE igdb_id = 267397 ON CONFLICT (game_id, language_code) DO NOTHING;
