INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tahl: Uncover the Evil Within', '"Tahl": Uncover the Evil Within is an isometric action RPG dungeon crawler where the player fights against hordes of ghosts and demons from East Asian mythology using point-and-click controls. There is no safe hub, so the player has to survive using the loot gained from enemies alone. This makes the game close to a roguelike, even though the dungeons are not randomly generated.' FROM games WHERE igdb_id = 145617 ON CONFLICT (game_id, language_code) DO NOTHING;
