INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rollcage: Limited Edition', 'Rollcage is a fast, furious 3D racing game from Psygnosis, combining elements from Death Rally with elements from Bullfrog''s classic Hi Octane: Race five other drivers in an immersive 3D environment while shooting at your peers and avoiding their retaliation. You have a wide selection of tracks and cars, along with options for multiplayer gaming and a vast array of configuration options. Cars can drive up walls, flip over, and continue driving. This makes for a very quick and fluid gameplay unlike any other at the time of this game''s release. The Limited Edition includes a bonus CD soundtrack featuring various artists.' FROM games WHERE igdb_id = 43736 ON CONFLICT (game_id, language_code) DO NOTHING;
