INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Jar Jar''s Journey Adventure Book', 'An interactive tale with fourteen animated pages, Jar Jar''s Journey is a CD-ROM designed to immerse children ages 4 and up in the exciting story of Star Wars: Episode I The Phantom Menace. In this adventure book, children will read along with Jar Jar, Queen Amidala, Anakin Skywalker, and Qui-Gon Jinn as they follow Jar Jar on his exciting adventure from the Naboo swamp to Tatooine.' FROM games WHERE igdb_id = 185866 ON CONFLICT (game_id, language_code) DO NOTHING;
