INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeff Gordon XS Racing', 'Jeff Gordon XS Racing is an action/arcade racing game with fierce competition. The vehicle designs are just as racy as the look and feel of the stock car tracks. Reach up to 300 mph and challenge yourself around steep banks and corkscrew loops. Jeff Gordon coaches you through the preliminaries, but the final test of your driving abilities is against Jeff Gordon himself.' FROM games WHERE igdb_id = 49888 ON CONFLICT (game_id, language_code) DO NOTHING;
