INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shiritsu Justice Gakuen: Nekketsu Seishun Nikki 2', 'This is a PlayStation-exclusive update to the original Rival Schools. It features two additional characters, Ran of Taiyo High School and Nagare of Gorin High School, as well a new version of the Nekketsu Seisyun Nikki school sim mode, which feature additional mini games and further plot developments over the original Japanese version of Shiritsu Justice Gakuen.' FROM games WHERE igdb_id = 44769 ON CONFLICT (game_id, language_code) DO NOTHING;
