INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bishi Bashi Special 2', 'Bishi Bashi (ビシバシチャンプ Bishi Bashi Chanpu?) is a series of Konami video games for arcades, mobile phones, PlayStation and Windows. All games in the series comprise playing through a wide variety of competitive minigames against other players. The arcade games support 1 to 6 players[1] and the PlayStation game allows 1 to 8 players; the game will provide computer opponents if there are not enough players.' FROM games WHERE igdb_id = 44840 ON CONFLICT (game_id, language_code) DO NOTHING;
