INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eliminator', 'Eliminator puts you in control of experimental hovering craft, running the gauntlet of various courses, dodging obstacles and blowing up opponents in an attempt to reach the end before an on-board bomb blows you up and out the game. As you progress through the game you gain the standard options of upgrades and the courses become trickier to navigate.' FROM games WHERE igdb_id = 81465 ON CONFLICT (game_id, language_code) DO NOTHING;
