INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carmageddon', 'Carmageddon for Sony PlayStation - is a unique version of the first game from the Carmageddon series. Due to the serious PlayStation''s hardware limitations nearly everything was done from scratch for this release. That is why all the levels are completely different from what was created for the original game. Also, the zombies were made as 3D models instead of sprites (by the way, there is no possibility to turn on pedestrians as an alternative to zombies, but their blood is still red).' FROM games WHERE igdb_id = 246895 ON CONFLICT (game_id, language_code) DO NOTHING;
