INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cydonia-mars-the-first-manned-mission', 73421, '1999-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/tu5puvkvtpllfmkfkphn.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cydonia: Mars - The First Manned Mission', 'Earth is dying, you, the player must save it by succeeding in the colonization of Mars. This is an adventure game that looks a lot like Cryo''s brand, meaning 3D pre-calculated graphisms, with smooth transition when moving from place to place, plus of course, the obligatory full-motion cut-scenes. The art is impeccably done and up to the standards of the release year (1998). Upon arriving on Mars, however, the landing module hits an unexpected force-field and crashes, and that''s where the adventure begins. The first puzzles are quite easy; they consist of saving the module and the two other humans aboard from the shipwreck and the subsequent fire, all the necessary hints being given to you by one of your shipmates. However, after that point, puzzles are way more difficult, as they consist (at first at least) of exploring remains of an alien civilization, with thought processes "alien" to human players.' FROM games WHERE igdb_id = 73421 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 73421 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
