INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('castrol-honda-world-superbike-team-superbike-racing', 139243, '1999-05-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob4e0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4ziq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castrol Honda: World Superbike Team - Superbike Racing', 'Castrol Honda Superbike Racing is a motorcycling game. The player can choose between four playing modes: practice session (just racing alone on a track), trainer session (following another bike to learn the ideal line), single race or championship (one season over all 14 courses). The two latter ones optionally also include a qualifying session. While there is only one bike (Honda RC 45). it is possible to change its setup (gearbox, front tire, rear tire, final drive, gears). Single races and championship can also be played with a second player in split-screen. The races include overall eight participants. Besides the eight difficulty levels and number of laps, the player can also enable/disable auto brake, help arrows, steering assist, wheelies, engine overheat, tire wear, loose rear wheel, penalties, bike damage and major damage. This game is in part based on Castrol Honda Superbike 2000.' FROM games WHERE igdb_id = 139243 ON CONFLICT (game_id, language_code) DO NOTHING;
