INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swarm Assault', 'Swarm Assault is a real time strategy game where you battle with swarms of ants, beetles, spiders, scorpions and wasps to control the map. Each of the 5 Colonies have 3 units you can build, there is no resource management as the stronger the unit is the longer it takes to hatch. In total there is 100 levels to progress through based on 4 different terrain types, also a level creator to generate your own maps.' FROM games WHERE igdb_id = 63166 ON CONFLICT (game_id, language_code) DO NOTHING;
