INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pumuckls Abenteuer bei den Piraten', 'Pumuckl is a small red-haired goblin character from a popular German TV series. His major concern is to trifle with humans. In this game Pumuckl''s help is needed to rescue a goblin family from the hands of the blue "Klabauterman". The player''s smartness is required to solve some puzzles, and one has to dig holes at the right place to defeat enemies.' FROM games WHERE igdb_id = 93124 ON CONFLICT (game_id, language_code) DO NOTHING;
