INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Michelle Kwan Figure Skating', 'Michelle Kwan Figure Skating is a computer game released in 1999, starring American figure skater Michelle Kwan. The player can create the skater, dress her, choose music and create a routine to it, and then compete in different skating competitions. While it does not follow the strict rules of international skating, there are logical reasons behind creating a program.' FROM games WHERE igdb_id = 307405 ON CONFLICT (game_id, language_code) DO NOTHING;
