INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack', 'Turn your PlayStation game console into a party! With original music, blistering humor, and a sarcastic host, You Don''t Know Jack whisks you from the green room to prime time at a pace so fast it''ll make your head spin. Get the question right and score some cash; get it wrong and pay the price.  Ready? Put your knowledge to the test and your ego on the line. You Don''t Know Jack is the quiz show party game where high culture and pop-culture collide.' FROM games WHERE igdb_id = 144785 ON CONFLICT (game_id, language_code) DO NOTHING;
