INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Josephine and Friends', 'Josephine and Friends is an educational game for children. You play as Josephine through summer and winter. In the summer you go on a fishing trip, play piano and solve assignments in the plot of vegetables. In the winter you can go snowboarding with Sofus, attend a concert or look for Melanie Mouse in her huge food cellar. This game contains many activities and a lot of songs. You can print out activities to do after the computer has been shut down, such as colour pictures, sing songs and cook.' FROM games WHERE igdb_id = 204726 ON CONFLICT (game_id, language_code) DO NOTHING;
