INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nyanyan Ga Nyan: Light Fantasy Gaiden', 'In the country village of Nekomura resides the cat tribe "Nyanyan". When the girls of the tribe reaches the age of 15 they have to pass the "adult ceremony" and when they pass the ceremony they get the "Choreography Command". The player controls the destiny of a little girl of the tribe that starts a journey to search a crystal ball. During her journey she will meet different characters, change and use different clothes, and will have to face a lot of dangers. The adventure is just beginning, join her until the end of her quest. This game was released only in Japan.' FROM games WHERE igdb_id = 44783 ON CONFLICT (game_id, language_code) DO NOTHING;
