INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Men in Black: The Series', 'The scum of the universe continue to slip through the cracks in the system and arrive on earth. As a Men in Black agent, it''s your job to stop them. Armed with advanced weapons including the noisy cricket, freezer gun, and grenade launcher, you will battle an array of aliens across New York, and even in space.' FROM games WHERE igdb_id = 49285 ON CONFLICT (game_id, language_code) DO NOTHING;
