INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dinosaur Adventure 3-D', 'A dinosaur-themed educational game. Should not be confused with 3-D Dinosaur Adventure. Velociraptor, Stegosaurus, the Mighty T-Rex: creatures your child has been fascinated with since the beginning of time. Now explore them on the computer! Welcome to Dinosaur Adventure 3-D, your virtual exploration in the prehistoric world of dinosaurs. This all-new version of the award-winning original combines the latest in 3-D technology with outrageous game play that your kids will love!' FROM games WHERE igdb_id = 69808 ON CONFLICT (game_id, language_code) DO NOTHING;
