INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Ultra Cool Pool', 'Do you love a good game of pool? Cool Pool has all your favorites - Eight Ball, Rotation, Cutthroat, Nine Ball, and Classic Pocket Billiards - on dazzling tables with a super-easy interface and with the option to use standard balls and custom balls. But Cool Pool also has five totally original "cool" games that''ll curl your cue and which can be played both on a standard or a differently shaped "cool" table. They give pool a whole new angle of strategy, surprise, and fun!' FROM games WHERE igdb_id = 183628 ON CONFLICT (game_id, language_code) DO NOTHING;
