INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wonder Stadium ''99', 'Released a mere five months after the original Wonder Stadium, Wonder Stadium ''99 does not add much in the way of gameplay. This update adds information about the 1999 Japanese baseball season to the game. The game gives you a selection of 14 fictional and professional teams as well as three different stadiums, just as the original did.' FROM games WHERE igdb_id = 37466 ON CONFLICT (game_id, language_code) DO NOTHING;
