INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Star Tennis 2000', 'This is a cartoon style tennis challenge that requires all your skill! Pick a character and journey through the game''s tournament mode, or simply try your hand in free mode. Choose from different court surfaces and different match setup options. Offering games for one to four players, All Star Tennis is a great way to enjoy the action on centre court.' FROM games WHERE igdb_id = 49880 ON CONFLICT (game_id, language_code) DO NOTHING;
