INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monsterseed', 45219, '1999-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4uzu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schdhp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monsterseed', 'Monster Seed obviously takes influence from the popular animal raising/fighting genre; specifically games like Pokémon and Monster Rancher. Of course, it does do a few things differently. One major difference is the fantasy setting. No ranches or medical settings here, no sir. Another key difference is in the overall presentation; Monster Seed''s gameplay and interface are a lot more simple than most other breeding games. Similar to mother games in the genre, there''s a brief tutorial of sorts, and then you''re off to gather your own creatures, earning better seeds and other breeding components as you go. Just be careful with your critters, because if they die in battle, they''re gone for good. Granted you can always breed more, but it can certainly set you back if your creature hatches at level five, but you lost a level twelve.' FROM games WHERE igdb_id = 45219 ON CONFLICT (game_id, language_code) DO NOTHING;
