INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Parker Brothers: Card Games', 'Parker Brothers: Card Games is a collection of card games licensed by Parker Brothers. The player can create a profile and go head-to-head with animated computer-controlled characters in one of nine classic card games: - Free Parking - Millie Bornes - Cribbage - Gin Rummy - Hearts - Racko - Rook - Solitaire - Spades Although the servers have long since been shut down, it was also possible to play a game online on Microsoft''s Zone.com online gaming service (now MSN Games).' FROM games WHERE igdb_id = 100093 ON CONFLICT (game_id, language_code) DO NOTHING;
