INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fun! Fun! Pingu', '''Fun! Fun! Pingu'' is a Japanese PlayStation title based on the children''s animation series ''Pingu''. The game follows Pingu in his escapades based on different episodes of the show, as he finds and picks up different items and talks with different citizens of Antartica. Alongside the release, various Pingu-branded PSX merchandise like controllers and memory cards were made.' FROM games WHERE igdb_id = 61678 ON CONFLICT (game_id, language_code) DO NOTHING;
