INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Submarine Commander', 'Introducing a whole new gaming experience.... JVC''s submarine commander puts you in control of a nuclear powered submarine and teaches you the stealth and tactics needed for anti submarine warfare. Using hi-tech weapons, sonar, radar and periscope you must defeat adversaries, control sea communication lines and dominate the maritime battlespace. Having passed these tests you can play in the games mission mode featuring over twenty tense command sorties.' FROM games WHERE igdb_id = 130269 ON CONFLICT (game_id, language_code) DO NOTHING;
