INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shanghai Mini', 'Shanghai Mini is a release in the series of Activision''s tile matching games. Included are classic, tournament and dynasty modes. Classic is normal game with six different board layouts. In tournament game player challenges the Tower of Shanghai and tries to beat the Shanghai Master by solving different board layouts within time limit. Dynasty is two player competition - against computer or human (requires link cable) opponent.' FROM games WHERE igdb_id = 43981 ON CONFLICT (game_id, language_code) DO NOTHING;
