INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Inquisition: Legacy', 'A free, multiplayer Multi-Used Dungeon (MUD) revolving around medieval religious oppression and the fight against magic in a fantasy world. The Holy Order is the dominant faith of the Kingdom of Lithmore and guides its followers with an iron grip. Experience a vast city filled with secrets. Craft and personalize hundreds of items. Engage in storylines, relationships and conflict with other players and staff-run plots. Cast fantastic spells in five different magical elements, or oppose magic through organised religion. Explore a setting 25 years in the making!' FROM games WHERE igdb_id = 228922 ON CONFLICT (game_id, language_code) DO NOTHING;
