INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('19-03-ueno-hatsu-yakou-ressha', 112552, '1999-03-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6svb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpwh6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '19:03 Ueno Hatsu Yakou Ressha', '19-03 Ueno Hatsu Yakou Ressha is a third person adventure game that tells the story of Tsupei Akai a freelance photographer or of Miyuki Hatakeyama a middle school teacher. Both of them take the night train that goes from Toyo''s Ueno to Sapporo but what started as a normal train travel soon will start to be a little more complicated since they will be involved into murders, assassins and other dangerous situations. The player can choose at the beginning of the game which story he wants to play and the situations and reactions of each character are different, so there is 2 adventures in the same game. The game is played in a first person perspective and is like an interactive movie and depending of the player choices his character will or not survive the travel. There are different endings and different death scenes.' FROM games WHERE igdb_id = 112552 ON CONFLICT (game_id, language_code) DO NOTHING;
