INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('minna-no-shogi-shokyuu-hen', 282231, '1999-12-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7lqa.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minna no Shogi: Shokyuu-hen', 'A shogi game suitable for beginners who are about to start shogi. The mode is "Shogi game function", which allows you to obtain the official diploma issued by the Japan Shogi Association for the first time by clearing the official league with a story, 200 recording problems, and you can enjoy tsume shogi from 1 to 5 tsume shogi. "Tsume shogi questioning function", "shogi technical term search function" that explains difficult technical terms in an easy-to-understand manner, and "communication battle function" that allows you to play against your friends.' FROM games WHERE igdb_id = 282231 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 282231 AND p.igdb_id = 22 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blademaker-arms-shop', 108825, '1999-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7chj.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blademaker: Arms Shop', 'The story begins with the protagonist, Aleph, receiving news of his father''s death. He left home almost five years ago, effectively running away, to study medicine. His return home is prompted by his sister Alola, their butler Royter, his daughter Belda, and a massive debt waiting for Aleph. They have half a year to repay the debt. If they can''t, they''ll not only lose their family home but also Alola. Aleph decides to take over the family business, a weapon shop, to pay off the debt. The game starts in january and ends at the end of June, if the player can''t pay the debt is game over. Each month is divided into 4 weeks, in those weeks the player can go around the town and buy materials and other items, he also can make new weapons and tools. Some customers will go to the shop and depending of the skills, the quality and the player''s reputation there will be more customers. On weekdays, you can sell items and commission artisans in your workshop to create weapons and tools. On Sundays, you can go into town to gather information and buy materials. There are also adventure events that the player have to solve, if he fails he got to do the same event in the last week or each month. There are different endings depending of the actions and reputation that the player got at the end of june, and the same if he pay or not the debt.' FROM games WHERE igdb_id = 108825 ON CONFLICT (game_id, language_code) DO NOTHING;
