INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Scooters', 'It''s time to grab your Hawaiian shirt, slap on your headphones and mount your scooter as you embark on the fastest, craziest, most frenetic racer on two wheels As well as racing against the wackiest bunch of misfits ever to be gathered on one screen, you also need to use your skills and judgement to avoid the hopping-mad cat, the flying chunks of Tuna and a small thing called road safety!' FROM games WHERE igdb_id = 279217 ON CONFLICT (game_id, language_code) DO NOTHING;
