INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('golgo-13--1', 131079, '1999-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4927.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scerqk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golgo-13', 'An arcade lightgun game adaptation of the Japanese manga series Golgo 13 developed by Eighting/Raizing and published by Namco. The player takes on the role of the titular character Duke Togo, aka Golgo 13, a professional assassin. The game takes the player on a series of assignments with different targets that need to be dispatched with a scoped rifle. At the end of each assignment the player is treated to on screen display of their performance. For each assignment successfully completed a large sum of cash is added to the player’s total, plus an extra sum is awarded for hitting the target zone. If however the player fails to complete the objective or the timer reaches zero, the player’s accuracy rating is reduced and the player is then moved on to choose the next assignment. The game is over when the player’s accuracy rating reaches zero. At the start of the player’s career, 5 different assignments are available to choose from and can be completed in any order. Once all 5 assignments have been undertaken a new round of assignments becomes available. In total there are 4 rounds each consisting of 5 assignments, with each round becoming progressively harder. The last round includes a special stage which can only be selected after all the assignments have been completed. Upon completion of the special stage the credits roll and the game ends. The player is then once again returned to the start of the game.' FROM games WHERE igdb_id = 131079 ON CONFLICT (game_id, language_code) DO NOTHING;
