INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of Fighters R-2', 'Mix it up in COLOR with King Of Fighters R-2 now on NEOGEO Pocket Color! Get SKILLS in the MAKING Mode and create your very own custom-made character! You can also play two-player VS. MODE battles and trade SKILLS using the NEOGEO Pocket Link Cable! 14 characters to choose from including 2 new characters make King Of Fighters R-2 H-O-T!' FROM games WHERE igdb_id = 43988 ON CONFLICT (game_id, language_code) DO NOTHING;
