INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sesame Street: Music Maker', 'Make music sing and play and learn along the way. Sesame Street Music Maker CD-ROM exposes your child to a variety of musical concepts and sounds that unusual instruments make. Eight activities are hosted by Sesame Street characters who guide and encourage your child to enjoy the wonders of music.' FROM games WHERE igdb_id = 138578 ON CONFLICT (game_id, language_code) DO NOTHING;
