INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deception-iii-dark-delusion', 26730, '1999-12-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coacqz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar433p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deception III: Dark Delusion', 'Taken against her will to Alendar Kingdom, Layna who becomes your challenge is now under the control of the evil King Frederick. As her life wears thin, it becomes your sole mission to ensure Layna saves herself as King Frederick''s mysterious organization attempts to bring Layna to her final doom. Through preparation of strategic trap setting you begin to plot and devise various techniques to destroy those who hold you captive. With over 2,000 trap variations it is up to you to choose the best combinations to assist you in conquering your enemy. Because there are multiple endings. Layna''s final fate may be your worst nightmare or ultimate fantasy. The choice is yours. The options are endless. * Over 2,000 trap variations * New and improved trap element system allows more freedom for players to develop traps. * Advanced 3D Polygon Graphics with Third Person Perspective. * Four modes of play are offered including the "Scenario Mode", "Trap License Mode", "Free Training Mode", and the "Expert Mode". * Multiple endings!' FROM games WHERE igdb_id = 26730 ON CONFLICT (game_id, language_code) DO NOTHING;
