INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Islamic Fun', 'Islamic Fun is a 1999 religious and educational video game, consisting of six minigames targeted at children. The game was developed by the United Kingdom-based firm Innovative Minds. The game is notable for its minigame "The Resistance" which allowed players to throw rocks at Israeli tanks upon correctly answering trivia.' FROM games WHERE igdb_id = 318628 ON CONFLICT (game_id, language_code) DO NOTHING;
