INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iron Maiden: Ed Hunter', 'Rail shooter based on Iron Maiden''s music and mascot, Eddie. The game was included as a bonus disc with the double CD compilation album of the same name. The game takes the player through a series of linear, on-rails missions through various levels based on the covers of past Iron Maiden albums. Players can select any track from the album to play in the background of each level.' FROM games WHERE igdb_id = 50360 ON CONFLICT (game_id, language_code) DO NOTHING;
