INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mickey''s Racing Adventure', 'While everyone is preparing for the town carnival, Pete sends his henchmen to steal all of the decorations. Now, it is up to Mickey, Minnie, Donald, Daisy, and Goofy to race Pete''s henchmen and reclaim the decorations. Race on 20 different courses that take place on land and water. By winning races, the characters earn coins that unlock bonuses. Put Pete and his cronies in their place with MICKEY''S RACING ADVENTURE.' FROM games WHERE igdb_id = 8128 ON CONFLICT (game_id, language_code) DO NOTHING;
