INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toyland Racing', 'The game is unexpected blend of racing and comics. What can be better than toys driving toy cars, even in such great Spanish cities as Madrid, Barcelona and Sevilla. You can drive with your friend in one car through 15 different tracks of the world under the guidance of Mr. Chetty. Here is different difficulty levels and multiplayer is up to 8 players.' FROM games WHERE igdb_id = 73764 ON CONFLICT (game_id, language_code) DO NOTHING;
