INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pachinko CR Mouretsu Genjin T', 'The popular platform "CR Moretsu Primitive Man T", which has gained overwhelming support from pachinko fans, is finally here. You can select a store on the map screen of the city, and in the store you can select a table by examining the nails on the up screen of the board. You can fully enjoy the fun actions unique to the reach and jackpot "Moretsu Primitive Man" on the enlarged screen. Of course, the prize money won can be carried over to the next time using a password.' FROM games WHERE igdb_id = 97624 ON CONFLICT (game_id, language_code) DO NOTHING;
