INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiffy''s Magical Tales: Pinocchio', 'Children can learn decision making skills as they help Pinocchio in this animated storybook which can be viewed in English, French, German or Russian. It includes 17 scenes, each displayed in full screen animation. Children can interact with the storyline, helping Pinocchio find money to buy Geppeto a vest, communicating with characters and even choosing how the action will develop. Pinocchio improves observation, listening, comprehension and problem solving skills.' FROM games WHERE igdb_id = 323976 ON CONFLICT (game_id, language_code) DO NOTHING;
