INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-neverland-2-pluto-kyouwakoku-monogatari', 77505, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5xxm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6bvf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Neverland 2: Pluto Kyouwakoku Monogatari', 'World Neverland 2: Pluto Kyouwakoku Monogatari is the second installment in the World Neverland series. Immerse yourself in the life of an ordinary citizen in the fantasy Waktic Republic of Pluto. Unlike traditional epic quests or world-spanning adventures, this game focuses on the simplicity of everyday life. Choose a profession, work, get married, raise kids, and eventually retire. At the beginning of the game, players have the freedom to explore the local area by navigating town with the D-pad and adjusting the screen size using the analog stick. Engage in activities like sword attacks with the "X" button and interact with fellow citizens using the "O" button. The passage of time occurs naturally, transitioning from day to night as you wander around town. Standing idly in the middle of town allows you to observe other citizens going about their daily routines. Occasionally, someone may approach your character, initiating a conversation or challenging you to a duel in a basic ring. The player''s role is crucial in reflecting the voice of the people to establish a peaceful country. Success in this endeavor can lead to membership in the council or even becoming the chairman. Along the way, players can take on various jobs, learn martial arts to become stronger, and maintain a social life with the diverse inhabitants of Pluto.' FROM games WHERE igdb_id = 77505 ON CONFLICT (game_id, language_code) DO NOTHING;
