INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 24: The Gun Shooting', 'Simple 1500 Series Vol. 24 - The Gun Shooting is a gun game set in the African continent in a near future in which the player (or players since the game features a 2 players cooperative mode) are 2 members of an organization with the mission of saving the continent from an alien army. The game is divided in different stages that are plains, rivers, mountains, etc. And at the end of each level there is a leevl boss that the player has to defeat to advance to the next one.' FROM games WHERE igdb_id = 203010 ON CONFLICT (game_id, language_code) DO NOTHING;
