INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Hunter', 'Battle Hunter (known as The Hunter in Europe) pits you against evil robots, mutated animals, and even some of your own friends! Battle Cards will help you get a leg up on the competition, and awesome action physics make the gameplay smooth and realistic. If you’re looking for an original challenge that lives up to its premise, check out BATTLE HUNTER.' FROM games WHERE igdb_id = 3190 ON CONFLICT (game_id, language_code) DO NOTHING;
