INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eisei Meijin III: Game Creator Yoshimura Nobuhiro no Zunou', 'Eisei Meijin III - Game Creator Yoshimura Nobuhiro no Zunou is a traditional video game released in 1999 by Konami for the Playstation & Dreamcast consoles. The game was only released in Japan. The game is based on the traditional board game shogi.' FROM games WHERE igdb_id = 283253 ON CONFLICT (game_id, language_code) DO NOTHING;
