INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FA Manager', 'FA Manager is the only football management simulation produced with the full endorsement of the Football Association. Working closely with the FA, the developers Krisalis have gained valuable knowledge of player contracts, wage and bonus structures and general "behind the scenes" dealings in order to create the most realistic soccer management game ever released on the Playstation.' FROM games WHERE igdb_id = 44818 ON CONFLICT (game_id, language_code) DO NOTHING;
