INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('interplay-sports-baseball-2000', 44735, '1999-04-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rirgoqjvpoccx9zeqwvu.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Interplay Sports Baseball 2000', 'Bottom of the 9th, two outs, and the game is tied. Bagwell steps up to the plate. He takes the first two pitches for strikes. The pitcher delivers the ball, and Bagwell knocks it out of the park. Astros win! Astros win! Live moments like these with INTERPLAY SPORTS BASEBALL 2000. Thanks to a Major League Baseball license, all of the teams, players, and stadiums are here. You can play an Exhibition game or a Home Run Derby to get some quick action, while those who have a little more time should experience the ups and downs of the Season, Tournament, or Playoff modes. For those who want to control everything, use the General Manager mode to trade players or create the perfect first baseman with the Create-a-Player option. The players look realistic thanks to motion capture technology. INTERPLAY SPORTS BASEBALL 2000 will challenge even the most die-hard baseball fans.' FROM games WHERE igdb_id = 44735 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 44735 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
