INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-18-world-tour-golf', 43821, '1999-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ye6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro 18: World Tour Golf', 'This golf game has TV-style presentation, with commentary by Peter Alliss and Bobby Clampett. Courses and players are photo-realistic, with course layouts accurate to within 3 centimetres. There are no fly-bys, although you can pan around the course to give some clues as to its layout. Four button presses are used to take a shot; draw and fade are set by how long the appropriate press is held down for. Several leading players are featured, including Colin Montgomerie and Vijay Singh as well as female and amateur players. There are three courses - Royal County Down, The Lost City and Couer D''Alene (plus Royal Birkdale on the North American edition).' FROM games WHERE igdb_id = 43821 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 43821 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
