INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hushaby Baby', 'In this game you had a girlfriend who died in a train accident about a month ago. One day, when you are going back to your home, you found her waiting at the door! The story starts from there and last for several days as you accompany her through the last days before the 49th day after she died...' FROM games WHERE igdb_id = 59216 ON CONFLICT (game_id, language_code) DO NOTHING;
