INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digital Keiba Shinbun: My Trackman', 'A simulation game by Shouei System for the Sega Dreamcast. It simulates an off-track betting station, allowing users who are connected to the Internet to bet on horse races from home. The service lasted a year and a half — Shouei System went bankrupt and shut the service down on October 1, 2000 at 17:00 (JST). The game may also be a standalone horse racing sim, however this is unconfirmed.' FROM games WHERE igdb_id = 283300 ON CONFLICT (game_id, language_code) DO NOTHING;
