INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neko Zamurai', 'Neko Zamurai places players in an old Japanese town set in the Edo period to enjoy multi story plots consisting of over 150 scenarios and featuring over 100 characters. In the conversation screen that forms the main part of gameplay, real time mime motion is adopted with the use of face tracker to give detailed and rich facial expressions to characters.' FROM games WHERE igdb_id = 128364 ON CONFLICT (game_id, language_code) DO NOTHING;
