INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Freeze', 'Deep Freeze is a 3D action-shooting game with pre-rendered backgrounds, similar to such games as Resident Evil and Parasite Eve only with a stronger action focus. Choose a partner from your squad for each mission, then make your way through each situation to eliminate the threat. You can give your partner orders, as well as change formation. The game features full voice acting completely in English, a rarity for a Japanese exclusive title.' FROM games WHERE igdb_id = 44757 ON CONFLICT (game_id, language_code) DO NOTHING;
