INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sinistar Unleashed', 'A remake of "Sinistar", the classic 80''s arcade game. In this game the player is sucked through a wormhole and thrown into the universe of Sinistar. Players must navigate 24 levels in order to beat the game, and destroy gates and sinistars while they are at it.' FROM games WHERE igdb_id = 20377 ON CONFLICT (game_id, language_code) DO NOTHING;
