INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyl: Dust', 'Dust is a Polish FPS by Optimus Nexus released in 1999. The player takes on the role of a former soldier fighting for his life on the distant moon Arena. Dust is one of the first Polish first-person shooters. It is distinguished by the necessity to use well-thought-out tactics to solve the encountered problems, because only good planning of actions allows you to survive in the hostile environment of the Arena. The game requires to use stealth and preserve ammunition in order to progress.' FROM games WHERE igdb_id = 116678 ON CONFLICT (game_id, language_code) DO NOTHING;
