INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinocchia no Miru Yume', 'You can choose between a male and female protagonist, and play as a doll/puppet maker who''s about to starve to death on Chirstmas Eve due to the inability to make a "pinocchia", a doll that looks and acts like a real human being (but isn''t truly alive), and make enough money to feed yourself. As you slip into unconsciousness, you plead to any higher being that''s listening to grant you a pinocchia, willing to give your life in exchange.... and wake up the next morning, with a "new-born" pinocchia in your hands.' FROM games WHERE igdb_id = 203288 ON CONFLICT (game_id, language_code) DO NOTHING;
