INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cool-boarders-4', 26131, '1999-11-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6q60.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ec3tnmwsjwmmtz5ydtlp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cool Boarders 4', 'Cool Boarders 4 features 16 real-life professional snowboarders ranging from 13 year-old prodigy Shaun White to veterans such as Noah Salasnek and living-legend Jim Rippey. Players also have the ability to custom-create a rider by selecting a body, choosing brand name attire and gear, and customizing any available board to your liking. Players can choose among 34 boards from Burton, Forum, K2, MLY, M3, Salomon, Ride, Morrow and Santa Cruz. There are over 30 new courses spread out over five authentic mountains that are filled with steep cliffs, drops, jumps, rails and various obstacles. Cool Boarders 4 also features Dirty Hands by hard rock artist, Outer Circle. And the game is compatible with the Dual Shock Analog Controller and your choice of memory cards.After three top sellers, Cool Boarders is still the slickest competition on the slopes. Cool Boarders 4 features big names like Jim Rippey, Ross Powers, Michele Taggart, J.P. Walker, Andrew Crawford, Shaun White and others; big boards like Burton, Fourm, K2, MLY, M3, Salomon, Ride, Morrow, Santa Cruz; big mountains and big features; big customization; a big trickmaster mode; big events; a big multiplayer tournament mode; big tricks; and big brawls.' FROM games WHERE igdb_id = 26131 ON CONFLICT (game_id, language_code) DO NOTHING;
