INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart ABC''s', 'JumpStart ABC''s (also sometimes referred to as JumpStart Learning Games: ABC''s) is a JumpStart game in the JumpStart Learning Games series released by Knowledge Adventure in 1999. It is based on the video JumpStart Preschool: Who Left the Juice in the Caboose?. In the game, Eleanor wants to find out who spilled his or her drink in the caboose and didn''t clean up the mess. The player accompanies her to visit each of her friends and find out was responsible for the spilled drink through a series of mini-games.' FROM games WHERE igdb_id = 92241 ON CONFLICT (game_id, language_code) DO NOTHING;
