INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart 1st Grade', 'JumpStart 1st Grade is a grade-based JumpStart game released by Knowledge Adventure in 1999. It teaches a 1st grade curriculum. It is an updated version of JumpStart 1st Grade (1995), and would later be replaced by JumpStart Advanced 1st Grade. In the game, the player helps Frankie the dog find treasures by completing activities around the school.' FROM games WHERE igdb_id = 176011 ON CONFLICT (game_id, language_code) DO NOTHING;
