INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Duel Monsters II: Dark Duel Stories', 'Yu-Gi-Oh! Duel Monsters II: Dark Duel Stories is a video game for the Game Boy Color, the sequel to Yu-Gi-Oh! Duel Monsters. Although the gameplay is still much simpler than the OCG, this game introduced 355 new cards, for a total of 720 (in contrast with the 365 total cards of its predecessor). Trap Cards and Ritual Spell Cards were first included in this game.' FROM games WHERE igdb_id = 56978 ON CONFLICT (game_id, language_code) DO NOTHING;
