INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Whyville', 'Whyville is an educational Internet site geared towards children from ages 8–14+ founded and managed by Numedeon, Inc. Whyville engages its users in learning about a broad range of topics, including science, business, art and geography. Whyville''s users (Whyvillians) engage in virtual world simulation based games and role play sponsored by a wide range of governmental, non-profit, and corporate entities. In 2009, the website had a registered base of more than 7 million users.' FROM games WHERE igdb_id = 203175 ON CONFLICT (game_id, language_code) DO NOTHING;
