INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'McDonald''s de Asobo!', 'Is a Sega Pico game released by Sega Toys in 2000. It is a simple restaurant management simulator, which although is sponsored by the American fast-food chain McDonald''s, was only released in Japan. McDonald''s de Asobo! is suspected to have originally shipped with plastic toys of Big Macs and cartons of fries - this may describe a separate release of the game, or the only release - full details are currently unknown.' FROM games WHERE igdb_id = 63044 ON CONFLICT (game_id, language_code) DO NOTHING;
