INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('power-shovel', 44741, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7swb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4q4o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Shovel', 'Based on Taito''s Japanese arcade game, Power Shovel puts players behind the controls of three earthmovers in a variety of construction-oriented events. Three modes of gameplay are available: Arcade King, License Mode, and Level Editor. Arcade King includes missions from the coin-op, such as demolishing a car, knocking over houses, and pouring large amounts of curry sauce over rice. Money earned in this mode is used to unlock more mini-games, artwork, music, and other items. Two players can also compete against each other in these events in a best of three competition. Players take turns completing each task until a winner is declared. License Mode provides a series of timed tests (like knocking over poles, parking and digging sand) that must be completed in order to gain your operator''s license. The Level Editor lets players design their own courses on a 6 x 6 grid, with obstacles such as holes, electric fences, cones, and sheds. The three available shovels vary in their size, speed, capacity, and digging ability. In each event, players have the option of a first- or third-person perspective.' FROM games WHERE igdb_id = 44741 ON CONFLICT (game_id, language_code) DO NOTHING;
