INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superlite 1500 Series: Pangaea', 'Pangaea is a multiplayer randomly-generated dungeon RPG designed to play like a board game. Nearly all actions in the game are decided by dice rolls, including the monsters fought, the effect of attacks and item use, contents of treasures, and even the layout of the dungeon itself -- entering an unmapped square will start a roll that decides the type of space that goes there.' FROM games WHERE igdb_id = 205715 ON CONFLICT (game_id, language_code) DO NOTHING;
