INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Learning: Toddler', 'Multi-subject learning software for toddlers; exercises young minds, encourages them to think and listen; practice their mouse skills, learn letters, numbers, colors, shapes and music, and sing along with their favorite characters.' FROM games WHERE igdb_id = 50478 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 50478 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 50478 AND c.slug = 'disney-interactive-victoria' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 50478 AND c.slug = 'disney-interactive' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 50478 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
